local quests = WordHunterWoW_QuestDataByFlavor.classic.deDE
quests[783] = { title = "Die Bedrohung von innen", description = "Ich hoffe, Ihr habt Euren Gürtel festgezurrt, $C, denn es gibt hier in Nordhain viel Arbeit.\n\nUnd ich meine damit nicht Landarbeit.\n\nDie Wachen von Stormwind haben alle Hände voll zu tun, um den Frieden zu bewahren; viele von uns weilen in fernen Ländern und viele Bedrohungen rücken immer näher. Deshalb rekrutieren wir jeden, der gewillt ist, seine Heimat zu verteidigen. Und die Allianz.\n\nFalls Ihr hier seid, um dem Aufruf zu folgen, sprecht mit meinem Vorgesetzten, Marshal McBride. Er ist in der Abtei hinter mir.", objectives = "Sprecht mit Marshal McBride.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[784] = { title = "Vernichtet die Verräter", description = "Angeführt von Admiral Proudmoore drangen die Menschen von Kul Tiras nach Durotar vor und brachen damit den Pakt, den der Kriegshäuptling vor Jahren mit Jaina Proudmoore geschlossen hatte, um Archimonde zu besiegen.\n\nDie Menschen-Aggressoren wurden zurückgeschlagen und Burg Tiragarde fiel. Kürzlich jedoch hat die Reserve des Admirals unter der Führung von Lieutenant Benedict die Burg zurückerobert und stellt erneut eine Bedrohung für unser Heimatland dar. Diese Menschen haben keinen Respekt vor Diplomatie.\n\nBeweist Eure Ehre und reist gen Süden zur Burg Tiragarde, um die Menschen-Eindringlinge zu eliminieren.", objectives = "Tötet 10 Matrosen von Kul Tiras, 8 Marinesoldaten von Kul Tiras sowie Lieutenant Benedict und kehrt dann zu Gar'Thok in Klingenhügel zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[786] = { title = "Vereitelung der Kolkaraggression", description = "Sprecht leiser, $C. Die Zentauren der Kolkar liegen gleich hinter jener Kuppe im Westen der Kolkarklippe.\n\nWährend ihres Angriffs letzte Nacht schlich ich mich in ihr Dorf und fand heraus, dass diese dreckigen Bestien einen dreistufigen Angriff auf die Trolle und Orcs von Durotar geplant hatten.\n\nIhre Invasion muss verhindert werden. Vielleicht könnt Ihr die Streitmacht zusammenziehen, die nötig ist, um die Kolkarklippe zu unterwandern und deren Angriffspläne zu vernichten.\n\nZuletzt sah ich, dass Sie sich auf drei ihrer Anführer verteilten.", objectives = "Lar Prowltusk außerhalb von Sen'jin möchte, dass Ihr die 3 Sets der Angriffspläne zerstört, die innerhalb der Kolkarklippe verwahrt werden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[787] = { title = "Die neue Horde", description = "Throm-ka, $C. Ich bin Eitrigg, von Thrall beauftragt, die Ausbildung der Rekruten zu beaufsichtigen.\n\nDie Horde ist nicht mehr das, was sie einmal war. Es gab eine Zeit, da ich die Horde verließ, enttäuscht durch den wachsenden Einfluss der machthungrigen Marionetten der Brennenden Legion. Während meines Exils wurde ich von einer Gruppe Menschen gefangen genommen, aber dann von dem Kriegshäuptling gerettet. Er erzählte mir von seiner Vision einer Horde, frei von dämonischen Einflüssen, von den Schamanen geleitet, und so kehrte ich zurück.\n\nGornek wird weitere Anweisungen für Euch haben.", objectives = "Meldet Euch bei Gornek beim Höhlenbau.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[788] = { title = "Scharfe Zähne", description = "Als Erstes werden wir Euer Rückgrat etwas kräftigen. Ich könnte Euch ins Brachland schicken, um Kodos zu jagen, aber mal ehrlich, lebend seid Ihr uns nützlicher als tot.\n\nIch glaube, die scheckigen Eber nördlich von hier wären genau das Richtige für Euch.", objectives = "Tötet 10 scheckige Eber und kehrt dann zu Gornek beim Höhlenbau zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[789] = { title = "Stich des Skorpiden", description = "Sowohl mächtige Krieger als auch tollpatschige Anfänger fallen dem Giftstachel der Skorpiden zum Opfer. Nordwestlich von hier findet Ihr eine größere Ansammlung Skorpiden. Bringt mir 10 ihrer Schwänze als Beweis für Eure Leistungsfähigkeit im Kampf.\n\nDas Gegengift für ihren Stich wird aus genau dem Gift, das aus ihren Stacheln extrahiert wurde, gewonnen. Wir haben immer einen großen Vorrat an Gegengift für dieses Skorpidgift, um Grünschnäbel wie Euch damit zu heilen...\n\nAber Ihr werdet das doch bestimmt nicht brauchen, oder?", objectives = "Bringt 10 Skorpidarbeiterschwänze zu Gornek im Höhlenbau.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[790] = { title = "Sarkoth", description = "$C! Ich dachte schon, ich müsste hier draußen sterben und niemand würde es bemerken. Auf der Jagd nach den Skorpiden des Tals stieß ich auf ein besonders heimtückisches Exemplar. Ich stürzte mich auf ihn und konnte einer seiner Klauen einen ordentlichen Draufschlag versetzen, bevor sie sich um mein Bein schloss.\n\nIch hatte jedoch nicht mit seinem Stecher gerechnet, den er tief in meine Brust trieb, mit dem er mein Fleisch zerschnitt und mir einen großen Blutverlust verursachte. Bitte, Ihr müsst den Skorpid für mich töten! Meine Ehre darf nicht besudelt werden! Da oben auf dem Plateau im Süden habe ich gegen ihn gekämpft.", objectives = "Tötet Sarkoth und bringt seine Klaue zu Hana'zua.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[791] = { title = "Akzeptiert Euer Schicksal", description = "Das Alter hat mich nutzlos für die Schlacht gemacht. Jetzt mache ich mich eben auf andere Weise nützlich.\n\nVon diesem Aussichtspunkt aus achte ich auf Eindringlinge. Während unsere Kraft hier zunimmt, muss ich mein Signalhorn immer seltener benutzen.\n\nUm mir die Zeit zu vertreiben, fertige ich Dinge an, die den jüngeren und fähigeren Kriegern bei der Verteidigung unserer Heimat helfen können.\n\nFür Euch könnte ich eine Tasche für Eure Habseligkeiten anfertigen. Falls ein solcher Gegenstand Euch nützlich sein könnte, bringt mir etwas Segeltuch, ein Material, das unter Menschen und Zentauren verbreitet ist.", objectives = "Furl Scornbrow im Wachturm von Klingenhügel möchte 8 Segeltuchreste haben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[792] = { title = "Üble Familiare", description = "Ich denke, das Tal der Prüfungen wird Euch viel lehren, $C.\n\nMan hat mich eigentlich ins Tal geschickt, um Euch anzuleiten, aber ich habe dort eine sich ausbreitende Besudelung entdeckt...\n\nEine Gruppe, die sich die 'Burning Blade' nennt, hat hier im Tal der Prüfungen einen Koven für ihre Mitglieder. Sie lungern im Nordosten in einer Höhle herum und ihre üblen Familiare kriechen daraus hervor, um Chaos anzurichten.\n\nAls erste Aktion gegen die Burning Blade bitte ich Euch, diese Familiare zu vernichten. Tötet so viele Ihr könnt, und falls Ihr überlebt, kehrt zu mir zurück.", objectives = "Tötet 12 üble Familiare.\n\nKehrt dann zu Zureetha Fargaze beim Höhlenbau zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[793] = { title = "Zerbrochene Allianzen", description = "Das Siegel der Erde wird von drei Runensteinen gebildet, die in der Lethlorklamm auf Säulen aus Diamant, Opal und Amethyst liegen. Ihr könnt die Runensteine mit Hilfe des Zeichens der Erde entfernen und so das Siegel der Erde brechen.\n\nSeid jedoch vorsichtig, $n, die Schwarzdrachen Schattenbringer und Hematus sollte man nicht unterschätzen. Tötet sie und kehrt mit ihren Bindungen zu mir zurück.\n\nUm die Klamm zu erreichen, müsst Ihr in den östlichsten Teil des Ödlandes reisen. Lasst jedoch Vorsicht walten, da die Klamm zahllose Drachen beherbergt.", objectives = "Benutzt das Zeichen der Erde, um die Säulen aus Diamant, Opal und Amethyst zu aktivieren und die Runensteine zu holen.\n\nLegt die Runensteine auf das Siegel der Erde, um Schattenbringer und Hematus zu befreien.\n\nTötet sie und bringt dann Gorn Schattenbringers Bindung, Hematus' Ketten und das Zeichen der Erde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[794] = { title = "Medaillon der Burning Blade", description = "Durch meine hellseherischen Kräfte weiß ich, dass im Koven der Burning Blade ein Gegenstand der Macht verborgen ist, der durch Bestien und schwarze Magie bewacht wird.\n\nEr wird das Medaillon der Burning Blade genannt und Eure nächste Aufgabe besteht darin, es zu finden und aus dem Koven zu entfernen.\n\nSeid jedoch vorsichtig, denn das Medaillon könnte im Besitz eines Agenten der Burning Blade sein, und falls dem so ist, ist die Macht dieses Agenten weitaus stärker als die der Familiare, auf die Ihr bereits gestoßen seid.\n\nGeht, $N. Ihr findet den Koven in einer Höhle im Norden und Westen.", objectives = "Bringt Zureetha Fargaze beim Höhlenbau das Medaillon der Burning Blade.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[795] = { title = "Siegel der Erde", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[804] = { title = "Sarkoth", description = "Was Ihr für mich getan habt, gibt mir Zuversicht. Ich darf nicht einfach so gehen! Ich muss durchhalten!\n\nOhne Hilfe schaffe ich jedoch den Weg zurück zum Höhlenbau nicht. Bitte, $n, kehrt zum Höhlenbau zurück und berichtet Gornek von meiner Lage. Vielleicht kann er mir helfen.", objectives = "Informiert Gornek beim Höhlenbau über Hana'zuas Notlage.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[805] = { title = "Bericht erstatten in Sen'jin", description = "Eure Prüfungen durch die Burning Blade sind beendet... jedenfalls hier im Tal. Ich möchte aber, dass Ihr von Euren Funden berichtet.\n\nBegebt Euch in das Trolldorf Sen'jin und sucht nach Meister Gadrin. Sen'jin liegt östlich hinter dem Tal und dann geht es an der Weggabelung nach rechts.\n\nBerichtet Gadrin von den Burning Blade und dass sie das Tal der Prüfungen erreicht haben. Bringt von ihm in Erfahrung, ob sie Sen'jin schon erreicht haben.\n\nGeht, $N, und beeilt Euch. Ich fürchte, dass das Böse, das wir im Koven der Burning Blade entdeckt haben, nur der Vorbote eines viel größeren Übels ist...", objectives = "Sprecht mit Meister Gadrin in Sen'jin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[806] = { title = "Dunkle Stürme", description = "Wir können den Burning Blade nicht erlauben, in Durotar Fuß zu fassen! Wir müssen sie vernichten, bevor das Böse zu schwären beginnt!\n\nIch habe selbst Nachforschungen unternommen und herausgefunden, dass ein Hexenmeister der Burning Blade, der Goblin Fizzle Dunkelsturm, nahe dem Donnergrat im Nordwesten kampiert. Er und seine Kultdiener verbreiten dort Chaos.\n\nSucht und besiegt Fizzle und bringt mir seine Klaue!", objectives = "Bringt Fizzles Klaue zu Orgnil Soulscar in Klingenhügel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[808] = { title = "Minshinas Schädel", description = "Ich höre die Stimme meines Bruders Minshina, der in meinen Träumen zu mir spricht.\n\nEr wurde von Zalazane, dem Hexenmeister auf den Echoinseln im Osten, gefangen genommen. Und er ist tot.\n\nAber der Tod bedeutet nicht Freiheit für meinen Bruder. Minshinas Geist ist durch Zalazanes Magie in seinem eigenen Schädel gefangen. In meinen Träumen sehe ich ihn zusammen mit weiteren Schädeln in einem Kreis der Macht auf der Größten der Echoinseln. Solange er dort bleibt, ist die Seele meines Bruders verdammt.\n\nBitte, $n. Sucht den Kreis und bringt Minshinas Schädel zurück. Bringt ihn mir.\n\nBefreit ihn!", objectives = "Holt Minshinas Schädel aus dem Kreis der Macht auf den Echoinseln.\n\nBringt ihn Meister Gadrin in Sen'jin.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[809] = { title = "Ak'Zeloth", description = "Seit dem letzten großen Krieg, in dem die Brennende Legion besiegt wurde, suche ich nach den Quellen dämonischer Verderbnis innerhalb der Orc-Gesellschaft. Das Halsband, das Ihr mir brachtet, bestätigt meine Befürchtungen.\n\nEs gehört den Burning Blade, einem Kult, der sich um einen Gegenstand dämonischer Macht schart. Er wird 'Dämonensaat' genannt und im Brachland hoch über dem Glutnebelgipfel aufbewahrt. Er muss zerstört werden!\n\nGeht zum Farwatch-Posten an der Grenze zum Brachland im Westen und sprecht dort mit meinem Assistenten Ak'Zeloth. Er wird Euch weitere Anweisungen geben.", objectives = "Sprecht im Brachland mit Ak'Zeloth.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[812] = { title = "Heilmittel benötigt", description = "$n, Ihr hättet den Zeitpunkt nicht besser wählen können. Ich hoffe nur, dass ich Euch auch zu Eurer Eile beglückwünschen kann.\n\nWährend eines Kampfes mit ein paar Siechstachelskorpiden war ich unvorsichtig und ich wurde von einem von ihnen heftig gestochen. Während wir uns unterhalten, spüre ich, wie sein Gift mich schwächt. Bei dieser Geschwindigkeit bleibt mir vielleicht noch eine Stunde zu leben. Aber selbst dazu brauche ich Eure Hilfe...\n\nKor'ghan in Orgrimmar weiß, wie man das Gegengift herstellt. Sucht ihn... und zwar schnell, $n. Ich werde nicht mehr lange durchhalten. Er sollte sich in der Kluft der Schatten befinden.", objectives = "Sucht Kor'ghan in Orgrimmar und besorgt das Siechstachelgegengift. Bringt das Gegengift dann zu Rhinag an der nordwestlichen Grenze von Durotar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[813] = { title = "Suche nach dem Gegengift", description = "Siechstachelskorpide sind eine der tödlichsten Skorpidarten in ganz Durotar. Es war dumm von Rhinag, sie zu jagen, ohne etwas von dem Gegengift mit sich zu führen, aber momentan ist eine ordentliche Standpauke das Letzte, was er benötigt.\n\nBringt mir ein paar Giftbeutel von den Siechstachelskorpiden in der Nähe des Eingangs nach Orgrimmar, dann stelle ich ein Gegengift für ihn her.\n\nBeeilt Euch, $n. Einer der Unseren braucht Eure Hilfe.", objectives = "Bringt Kor'ghan in Orgrimmar 4 Giftbeutel eines Siechstachelskorpiden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[815] = { title = "Zerbrecht ein paar Eier", description = "Pah! Jetzt hätte ich doch beinahe vergessen, Frühstück zu machen.\n\n$n, setzt Euch in Bewegung und bringt mir ein paar Schwanzpeitschereier. Ich brauche mindestens drei davon, wenn ich genug für die morgige Mahlzeit haben möchte.\n\nDie Blutkrallenschwanzpeitscher können ganz schön wild sein und beschützen ihre Eier bis in den Tod. Manchmal vergraben sie ihre Eier allerdings zu tief in der Erde, um sie sicher ausgraben zu können, aber reist doch zu den Echoinseln südöstlich von Sen'jin, dort findet man sie gewöhnlich überall auf den Inseln verteilt.", objectives = "Bringt dem Koch Torka in Klingenhügel 3 Schwanzpeitscher-Eier.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[816] = { title = "Verloren, aber nicht vergessen", description = "$N, bitte, könnt Ihr mir helfen? Mein Sohn Kron ist vor Tagen auf die Jagd gegangen und immer noch nicht zurück. Er wollte nach Westen in Richtung des Brachlandes, um dort am Ufer des Südstroms Krokilisken zu jagen. Ich fürchte das Schlimmste.\n\nSo stark wie er ist, hat ihn sein starrköpfiger Stolz doch immer wieder in Schwierigkeiten gebracht. Ich habe ihn gewarnt, dass die Krokilisken mächtig und heimtückisch sind. Er wurde wütend und stürmte davon.\n\nFalls Ihr ihn nicht finden könnt, so bringt mir doch wenigstens einen Hinweis darauf, was aus ihm geworden ist ... und wenn Ihr dazu jedem einzelnen Krokilisken an den Ufern des Südstroms den Bauch aufschlitzen müsst.", objectives = "Bringt Misha Tor'kren auf dem Bauernhof nordwestlich von Klingenhügel einen Hinweis auf Krons Schicksal.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[817] = { title = "Praktische Beute", description = "Viele der Bälge, die wir benutzen, stammen von den Durotar-Tigern, $N. Decken, Rüstungen, Zelte: Es gibt viele Gründe, warum wir Jagd auf die Wildtiere machen, und ebenso viele Gründe, warum wir sie leben lassen.\n\nDie Zeit ist gekommen, dass wir den Bestand dezimieren. Wir werden immer mehr, und unser Bedarf übersteigt bald unsere Bestände. Ich brauche mehr Bälge, wenn ich geeignete Dinge für unser Volk anfertigen möchte.\n\nBringt mir 4 Durotar-Tigerfelle, dann werde ich Euch belohnen. Ihr findet sie auf den Inseln südlich von hier.", objectives = "Bringt Vel'rin Fang in Sen'jin 4 Durotar-Tigerfelle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[818] = { title = "Ein geistvolles Getränk", description = "Meine Augen sind zwar nicht mehr so scharf, aber ich kann immer noch gut genug sehen. Immer öfter muss ich mich auf meine Alchimie-Fertigkeiten verlassen, um mir bei Dingen, die mir früher leicht fielen, nun mit Magie zu helfen. Ich weigere mich jedoch, einen Lehrling einzustellen - bislang ist mir noch kein Troll oder Orc begegnet, der sich als würdig genug erwiesen hätte.\n\nSeid Ihr dessen würdig? Ja, natürlich seid Ihr das... natürlich glaubt Ihr, dass Ihr es seid.\n\nIch brauche ein paar Dinge. Würdet Ihr sie für mich besorgen?\n\nIch brauche intakte Makruraaugen und Phiolen mit Kriechersekret. Ihr findet das überall in Durotar, wo es Makruras oder Kriecher gibt. Wir sehen uns bald wieder.", objectives = "Bringt Meister Vornal in Sen'jin 4 intakte Makruraaugen und 8 Phiolen Kriechersekret.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[819] = { title = "Chens leeres Fässchen", description = "Auf einem kleinen Schild an einem Ende des Fässchens steht:\n\n\"Chen Stormstout -\n\nMöge es Euren Geist erheben und Euch Mut machen.\"", objectives = "Sucht jemanden, der etwas über Chens leeres Fässchen weiß.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[821] = { title = "Chens leeres Fässchen", description = "Möchtet Ihr eine Kostprobe von Chens Namensvetter? Ahh, das Stormstout ist ein gehaltvolles Gebräu. Chen gab das Rezept an meinen Mentor weiter und mein Mentor gab es mir. Ich möchte, dass Ihr mir ein paar Dinge besorgt, aber eins möchte ich Euch sagen: Der Kick ist es wert.\n\nBringt mir 5 Savannenlöwenhauer von beliebigen Savannenlöwen, 5 Ebenenschreiternieren von beliebigen Ebenenschreitern und 1 Donnerechsenhorn von einer Sturmschnauze. Das sollte bestens funktionieren.\n\nIhr findet diese Zutaten überall im Brachland.", objectives = "Bringt Braumeister Drohn in Ratchet 5 Savannenlöwenhauer, 5 Ebenenschreiternieren und 1 Donnerechsenhorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[822] = { title = "Chens leeres Fässchen", description = "Gutes Zeug, dieses Stormstout, was?\n\nIch habe noch ein Rezept, das ich von Chen gelernt habe. Hättet Ihr Interesse? Die Herstellung dauert nicht lange und es könnte Euch nützlich sein, wenn Ihr Eure Abenteuer fortsetzen wollt.\n\nBringt mir 5 Blitzschlagdrüsen einer beliebigen Sturmechse, 1 Donnerfalkenspeicheldrüse von großen Donnerfalken und eine Kodoleber einer beliebigen Kodoart des Brachlandes.\n\nWie ich sagte, das Zeug hat es in sich; das ist das Troggbräu, das ich kürzlich erwähnte.", objectives = "Bringt Braumeister Drohn in Ratchet 5 Blitzschlagdrüsen, 1 Donnerfalkenspeicheldrüse und 1 Kodoleber.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[823] = { title = "Bericht an Orgnil", description = "Auch wir in Sen'jin sind nicht ohne eigene Probleme und wir danken Euch für Eure Hilfe. Aber die Neuigkeiten, die Ihr über die Burning Blade bringt, können Probleme für jedermann bedeuten.\n\nIn Klingenhügel ist ein Orc stationiert, Orgnil Soulscar, der Durotar vor solch Bösem wie den Burning Blade bewacht! Geht zu Orgnil und berichtet ihm von unserer Not sowie von Euren Neuigkeiten über das Tal der Prüfungen. Er wird diese Dinge wissen wollen.\n\nKlingenhügel liegt im Norden.", objectives = "Sprecht mit Orgnil Soulscar in Klingenhügel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[824] = { title = "Je'neu vom Irdenen Ring", description = "Der Irdene Ring ist eine schamanistische Gruppe, die sich dem Studium und dem Erhalt der Elemente widmet. Sie hat bereits mehr über verrückte alte Götter und uralte Legenden und Lehren vergessen, als die meisten Gelehrten jemals in Erfahrung bringen werden.\n\nZu Eurem Glück kenne ich jemanden hier in Ashenvale, der Mitglied des Irdenen Rings ist. Geht hinüber zum Zoram'gar-Außenposten an der Küste des Zoramstrandes; zeigt Je'neu Sancrea, was Ihr gefunden habt. Wenn überhaupt jemand die Bedeutung dieser Kugel herausfinden kann, dann er.", objectives = "Bringt die beschmutzte Wasserkugel zu Je'neu Sancrea im Zoram'gar-Außenposten in Ashenvale.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[825] = { title = "Aus den Wrackteilen geborgen...", description = "Einer meiner aufmerksamsten Späher hat mir Kunde gebracht, dass die Trümmer von Proudmoores Flotte immer noch an der Küste Durotars liegen, gleich östlich von Burg Tiragarde.\n\nEs ist kein Geheimnis, dass die Menschen, die sich mit diesen elenden kleinen, als Gnome bekannte Kreaturen verbündet haben, über reichliches Wissen auf dem Gebiet der Mechanik verfügen. Wir müssen so viel wie möglich über unsere potenziellen Feinde in Erfahrung bringen. Dann kann unser Volk von diesem neuen Wissen profitieren.\n\nSchwimmt durch die Wrackteile, $n, und bringt mir die Werkzeuge der Allianz.", objectives = "Gar'Thok von Klingenhügel möchte, dass Ihr 3 Gnomen-Werkzeuge aus den Wrackteilen vor der Küste holt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[826] = { title = "Zalazane", description = "Der Hexendoktor Zalazane lebt auf den Echoinseln im Osten. Das sind die Inseln, die wir einst Heimat nannten.\n\nVon dort aus entsendet er seine Trolle zum Festland, wo sie unser Volk verhexen und immer mehr von uns in ihren Bann ziehen.\n\nEr muss aufgehalten werden.\n\nBesiegt Zalazane und seine Diener - ehemalige Trolle der Darkspear, die jetzt nicht mehr zu uns gehören. Bringt mir seinen Kopf, dann weiß ich, dass seine Schreckensherrschaft vorbei ist.", objectives = "Besiegt Zalazane.\n\nTötet 8 Voodootrolle und 8 verhexte Trolle.\n\nBringt Gadrin Zalazanes Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[827] = { title = "Die Knochenhöhle", description = "$N. Die Burning Blade haben die Knochenhöhle östlich von Orgrimmar besetzt. Sie führen in dieser Höhle schlimme Rituale durch und fügen sich durch Senghalsbänder selbst Brandwunden zu.\n\nIch glaube, indem sie diese Halsbänder tragen, bringen die Kultisten sich im Einklang mit dämonischen Mächten. Um das zu bestätigen, benötige ich jedoch ein paar dieser Halsbänder, um sie zu studieren.\n\nGeht zur Knochenhöhle und besorgt ein paar Senghalsbänder von den Kultisten, die Ihr dort findet. Bringt sie mir, dann werde ich ihre Geheimnisse enthüllen.", objectives = "Besorgt von den Kultisten an der Knochenhöhle ein paar Senghalsbänder.\n\nBringt sie Margoz in seinem Lager.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[828] = { title = "Margoz", description = "Margoz, einer unserer Schamanen, weiß mehr über die Verderbnis der Burning Blade. Er sprach von einer Höhle namens Knochenhöhle in den Bergen - gleich vor den Toren Orgrimmars! - dort soll sich eine große Gruppe von Kultisten der Burning Blade eingenistet haben.\n\nBevor Ihr jedoch zur Knochenhöhle geht, sprecht mit Margoz. Er ist weise und sein Rat wird geschätzt.\n\nEr lagert im Nordosten zwischen der Küste und der Staubwindklamm.\n\nFolgt seinem Rat, aber was immer Margoz auch sagt, $N, ich möchte, dass Ihr diese Kultisten vernichtet!", objectives = "Sprecht mit Margoz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[829] = { title = "Neeru Feuerklinge", description = "Die Senghalsbänder, die Ihr mir brachtet, sind mächtige, dämonische Werkzeuge. Ihre Herkunft zu bestimmen liegt jedoch leider außerhalb meiner Künste als Schamane. Wir werden einen Hexenmeister bitten müssen, sie zu studieren.\n\nBringt ein Senghalsband zu Neeru Fireblade. Er ist zwar ein talentierter Hexenmeister, doch nutzt er seine Mächte nur, um Dämonen zu bekämpfen, und er behauptet, dass seine Forschungen auf dem Gebiet des Okkultismus gutartiger Natur sind. Ob es stimmt oder nicht, wir brauchen dennoch seine Hilfe gegen den Dämonenkult in Durotar.\n\nIhr findet Neeru in Orgrimmar in der Kluft der Schatten.", objectives = "Bringt Neeru Fireblade in Orgrimmar ein Senghalsband-Muster.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[830] = { title = "Die Befehle des Admirals", description = "Ihr öffnet den alten, verwitterten Umschlag und findet darin ein offiziell aussehendes Dokument. Ihr erkennt das Siegel Admiral Proudmoores.\n\nEs sieht wichtig aus. Vielleicht wäre Gar'Thok, Kommandant von Klingenhügel, an diesen Informationen interessiert.", objectives = "Bringt Gar'Thok in Klingenhügel Admiral Proudmoores Befehle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[831] = { title = "Die Befehle des Admirals", description = "Menschen kann man nicht trauen. Wir haben immer mit wachsamen Augen an ihrer Seite gekämpft, weil wir wussten, dass sie uns eines Tages verraten würden.\n\nLeider war Admiral Proudmoores Tod nicht genug, um sein Vermächtnis des Betrugs aufzuhalten. Der Menschenabschaum hatte vor seinem Ableben alles gut durchgeplant.\n\nSeine Herrschaft würde, wie es scheint, nicht einmal mit Benedict enden. Wer weiß, wann die nächste Welle von Proudmoores Männern an unseren Küsten landen wird.\n\nWir müssen diese Befehle sofort zu Nazgrel in Orgrimmar bringen! Man findet ihn in Thralls Kammer.", objectives = "Bringt Nazgrel in Thralls Kammer in Orgrimmar Admiral Proudmoores Befehle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[832] = { title = "Brennende Schatten", description = "<Die Stimme aus dem Anhänger erreicht direkt Euren Verstand.>\n\nGazz'uz?\n\nGazz'uz... Bericht!\n\nMan hat von Eurer Entdeckung in der Knochenhöhle gehört. Ihr müsst Euch auf einen Angriff vorbereiten!\n\nGazz'uz, ich befehle Euch, mir zu antworten! Sagt etwas, sonst werde ich dafür sorgen, dass Neeru Fireblade von Eurer Anwesenheit erfährt, dann wird es Euch schlecht ergehen.\n\nVersucht nicht, Eure Fertigkeiten mit denen Neerus zu messen...\n\n... Gazz'uz, seid Ihr da...?", objectives = "Bringt Neeru Fireblade dieses Auge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[833] = { title = "Eine heilige Bestattung", description = "Nur die tapfersten Tauren werden bei den Teufelsfelsen, unserer heiligen Begräbnisstätte, bestattet. Es ist eine Ehre, die jenen großen Kriegern zuteil wird, die dazu beitrugen, Thunder Bluff zu gründen und zu verteidigen, und jenen, die ihr Leben für das Wohl ihres Stammes und ihrer Häuptlinge gegeben haben.\n\nNun sieht es jedoch so aus, als wäre es einer üblen Bedrohung gelungen, in unser heiliges Land einzudringen. Eine Gruppe Borstennacken-Eindringlinge verheert das Grabmal und ich bin zu alt und gebrechlich, um sie selbst zu vertreiben.\n\nSie müssen mit Gewalt von dort verjagt werden, $N.", objectives = "Der Hüter des Wissens Raintotem möchte, dass Ihr bei den Teufelsfelsen 8 Eindringlinge der Borstennacken tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[834] = { title = "Wind in der Wüste", description = "Ich bin Rezlak, einer von Gazlowes Jungs. Boss hat mich geschickt, den Orcs hier in Durotar unter die Arme zu greifen. Soweit läuft alles klar, abgesehen von den Karawanen. Ich schaff's einfach nicht, sie zu sichern! Das erschwert mir meinen Job ganz schön, wisst Ihr?\n\nDie letzte Lieferung, meine Güte, die hatten garantiert, dass sie durchkommt! Aber sie wurde von den Staubschwingenharpyien von... wo war das noch... in der Klingenschlucht geklaut.\n\nIch muss dieses Zeug zurückhaben, sonst kriege ich hier nie mehr was zu tun! Folgt dem großen Canyon nach Süden, dort findet Ihr eine Klamm direkt westlich und östlich der Wände.", objectives = "Holt 5 Säcke Vorräte und bringt sie Rezlak in der Nähe von Orgrimmar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[835] = { title = "Sicherung der Linien", description = "Gazlowe sagte mal zu mir: \"Rezlak. Eines musst du im Leben wissen: Wenn du was richtig gemacht haben willst, dann tu's selbst.\"\n\nIch kann es mir nicht leisten, all unsere Karawanen zu verlieren, also muss ich die Sache selbst in die Hand nehmen. Die Staubwindklamm liegt hinter dem Ostteil der Klingenschlucht. Wenn wir alle Harpyien dort töten, ist die Route wieder sicher.\n\nNatürlich gab's da noch was, das Gazlowe mir beigebracht hat, und das ist: \"Wenn die Kohle stimmt, kriegt man alles.\" Also, werdet Ihr mir helfen, $n?", objectives = "Tötet für Rezlak in der Nähe der Staubwindklamm 12 Wilde der Staubschwingen und 8 Sturmhexen der Staubschwingen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[836] = { title = "Rettet OOX-09/HL!", description = "Aus dem Roboter ertönt erneut die blecherne Stimme des Gnoms:\n\n\"Ich muss OOX-09/HL an einen offenen, sicheren Ort schaffen, wo er die langwierige Startprozedur beginnen kann. Er hat eine eingebaute Tarnvorrichtung, aber ich brauche etwas Zeit, um sie von hier aus wieder funktionstüchtig zu machen. Eskortiert den Roboter von seinem derzeitigen Standort... hmmm, ja, zur Küste jenseits der Aussichtsklippen! Das sollte der perfekte Ort für mein Vorhaben sein, und bis Ihr dort seid, sollte ich auch alles vorbereitet haben und online gehen können.\"\n\n\"Eskortiert ihn sicher bis zur Küste und kommt dann zu mir nach Booty Bay! Oglethorpe Obnoticus - Ende!\"", objectives = "Eskortiert OOX-09/HL zur Küste jenseits der Aussichtsklippen und meldet Euch dann bei Oglethorpe Obnoticus in Booty Bay.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[837] = { title = "Übergriff", description = "Als wir hier ankamen, war ein Großteil des Landes im Besitz der Grimmhauerstacheleber, die sich als ein ziemlicher Dorn im Auge erwiesen. Durch unsere Anstrengungen konnten wir einen großen Teil von ihnen vertreiben, aber es gibt doch noch welche, die sich in einigen Gebieten verschanzt haben.\n\nDas geht jetzt jedoch schon viel zu lange so. Zu unserer eigenen Sicherheit dürfen wir nicht zulassen, dass sich die Grimmhauer in unserem Land festsetzen. Ihre Lager befinden sich westlich von hier. Sucht nach dem Dornengestrüpp, dann findet Ihr sie. Heute vertreiben wir sie aus Durotar, morgen vielleicht schon aus Kalimdor.", objectives = "Tötet für Gar'Thok in Klingenhügel 4 Stacheleber der Grimmhauer, 4 Späher der Grimmhauer, 4 Staubläufer der Grimmhauer und 4 Schlachtwachen der Grimmhauer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[838] = { title = "Scholomance", description = "Auf der Insel Caer Darrow liegt die Scholomance - eine Schule, die als Festung für die Geißel dient. Unser Feind haust dort, wo er sicher Forschungen betreiben kann, die seine Macht stärken. Eine Tür versperrt den Weg, und ganz gleich was wir versuchen, der Zutritt ist nur mit dem richtigen Schlüssel möglich.\n\nApotheker Dithers weiß viel über die Scholomance und hat eine Idee, wie ein Schlüssel zu erlangen ist. Ihr habt mir Euren Wert als jemand bewiesen, der knifflige Dinge erledigen kann; ich vertraue Euch nun diese Aufgabe an. Sprecht mit ihm über diese Angelegenheit.", objectives = "Sprecht mit Apotheker Dithers am Bollwerk, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[840] = { title = "Freiwilliger der Horde", description = "Hmmm, Ihr seht mir recht stark aus.\n\nHört mal, mein guter Freund Kargal braucht ein paar neue Rekruten für den Dienst im Brachland. Ich weiß, dass Ihr immer nur das Richtige für die Horde tun wollt. Das ist jetzt Eure Chance.\n\nBringt Kargal diesen Anwerbungsbrief und seht, ob er ihn unterzeichnet.", objectives = "Folgt der westlichen Straße aus Klingenhügel ins Brachland und über die Brücke.\n\nMacht bei dem Außenposten der Orcs auf der anderen Seite Halt.\n\nGebt Kargal Battlescar im Brachlandaußenposten Euren Anwerbungsbrief.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[841] = { title = "Eine weitere Kraftquelle?", description = "Ich stelle mal eine Vermutung an - Ihr habt, welch weltbeendende, ruchlose Tat Ihr auch unternommen habt, diese Tat nicht rechtzeitig beendet. Nein, wartet, noch besser... Ihr habt die Sache in den Sand gesetzt! Nun, was auch immer der Grund sein mag, ich verfüge über eine weitere Kraftquelle, die ich Euch verkaufen werde. Dieses Mal wird sie Euch aber zehn, JAWOHL ZEHN Wasserbeutel eines Wüstenläufers kosten!\n\nDie Zeiten hier sind schwer, $n, und Kraftquellen wachsen nicht auf Bäumen! Hmm, aber was wäre wohl, wenn sie es täten... Vielleicht könnten wir einen Kraftquellenbaum MACHEN...", objectives = "Bringt Chefingenieur Bilgewhizzle in Gadgetzan 10 Wasserbeutel eines Wüstenläufers im Austausch gegen eine weitere Kraftquelle.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[842] = { title = "Crossroads-Wehrpflicht", description = "Bringt diesen unterzeichneten Anwerbungsbrief nach Crossroads.\n\nSergra Darkthorn, verflucht sei sie, hat dort das Kommando. Sie ist eine grässliche Schamanin, die Euch erst schwindelig redet, bevor Sie Euch etwas Nützliches tun lässt. Thrall ist davon überzeugt, dass sie etwas ganz Besonderes ist, aber ich bin mir da nicht so sicher.\n\nMacht Euch selbst ein Bild davon, Jungspund ...", objectives = "Folgt der Straße von Kargals fernem Farwatch-Außenposten nach Westen.\n\nWendet Euch bei der Einmündung nach links und folgt dann der Straße in südliche Richtung. \n\nSucht Sergra Darkthorn an der Kreuzung zweier Straßen in Crossroads auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[843] = { title = "Ganns Rekultivierung", description = "In Einsamkeit wandere ich auf diesen Straßen.\n\nDie Zwerge Bael Modans haben keinen Respekt vor meinem Land. Entsetzliche Schläge reißen tiefe Wunden in den Boden und brüllende Maschinen zerfetzen die Hügel. Land, das meinem Stamm einst als Heimat und Versorger diente, ist jetzt von zerstörerischen Zwergen durchfurcht.\n\nAlle Versuche, zu einer diplomatischen Einigung zu kommen, sind fehlgeschlagen. Jetzt ist die Zeit für entschlossenes Handeln gekommen.\n\nVertreibt die Zwerge mit Gewalt von der Bael Modan-Ausgrabung und bringt mir das Tagebuch ihres Anführers, Ausgrabungsleiter Khazgorm.", objectives = "Gann Stonespire möchte, dass Ihr 15 Ausgräber von Bael'dun und 5 Großknechte von Bael'dun tötet.\n\nBringt Gann Stonespire dann Khazgorms Tagebuch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[844] = { title = "Ebenenschreiter-Bedrohung", description = "Eure erste Beute wird einfach sein.\n\nDie Ebenenschreiter im Osten fallen immer wieder über unsere Lebensmittelvorräte her und sind zu einer Plage geworden.\n\nVernichtet die Ebenenschreiter und bringt mir ihre Schnäbel.", objectives = "Besorgt 7 Ebenenschreiterschnäbel und bringt sie Sergra Darkthorn in Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[845] = { title = "Die Zhevras", description = "Die Zhevras sind etwas wilder als die Ebenenschreiter, auch wenn sie nicht die stärksten Wildtiere im Brachland sind. Aber macht Euch keine Sorgen - wir werden Euch bei Gelegenheit gegen größere Beute ausschicken. Vorerst könnt Ihr jedoch noch ein bisschen Übung gebrauchen.\n\nJagt die Zhevras im Norden und Süden und sammelt ihre Hufe. Bringt sie mir, und vielleicht werden wir Euch als Nächstes eine schwierigere Aufgabe stellen.", objectives = "Erschlagt Zhevra-Läufer, um für Sergra Darkthorn in Crossroads 4 Zhevra-Hufe zu erhalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[846] = { title = "Ganns Rache", description = "Es ist klar, dass ein Ausgrabungsleiter von Sprengstoff und diesen lärmenden Fahrzeugen abhängig ist, um den Boden aufzureißen. Wir müssen damit rechnen, dass schon bald ein neuer Großknecht die Sache übernimmt.\n\nIch möchte den Zwergen ihre eigene Medizin zu schmecken geben. Wenn wir laut diesen Plänen Nitroglyzerin mit Holzbrei und Natriumnitrat mischen, erhalten wir eine Sprengladung. Es ist bekannt, dass die Scharfschützen, Soldaten und Offiziere in der Burg diese Dinge besitzen.\n\nHolt diese Sachen und bringt sie mir; ich werde daraus eine Sprengladung basteln, die die Zwerge so schnell nicht vergessen werden!", objectives = "Gann Stonespire möchte, dass Ihr ihm 6 Phiolen Nitroglyzerin, 6 Teile Holzbrei und 6 Proben Natriumnitrat bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[847] = { title = "Arglist des Raptors", description = "Diese... diese Macht... Ist das die Macht der Schamanen, die Tor'gan mir zeigen wollte? Ich muss sagen, das ist wirklich interessant. Sagt Tor'gan, dass er mich überzeugt hat... jedenfalls für den Augenblick. Ich werde mir anhören, was er zu sagen hat.", objectives = "Sprecht mit Tor'gan.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[848] = { title = "Pilzsporen", description = "Die Oasen des Brachlandes verbergen ein Mysterium. In ihren Wassern fließt Lebensenergie, die alle Pflanzen und Wildtiere erquickt, die davon trinken.\n\nErquickt und verändert.\n\nEs gibt einen Pilz, der in der Nähe dieser Oasen wächst. Seine Sporen besitzen Eigenschaften, die wir, die Apotheker Lordaerons, sehr nützlich finden.\n\nBringt mir diese Sporen, dann seid Ihr unserer Dankbarkeit gewiss.", objectives = "Bringt dem Apotheker Helbrim in Crossroads 4 Pilzsporen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[849] = { title = "Ganns Rache", description = "Wenn wir uns an Khazgorms Pläne halten, sollte es eigentlich kein Problem sein, eine Sprengladung herzustellen.\n\nAh, fertig.\n\nAlso, $n, ich möchte Euch mit einer besonderen Aufgabe betrauen. Nehmt diese Dynamitstange und jagt damit den Flugapparat bei Bael Modan in die Luft.\n\nDieser Flugapparat ist nicht nur ein wichtiger Bestandteil der Infrastruktur der Grabungsstätte, sondern auch eine Kriegswaffe. Vor allem ist sie aber ein Symbol der Macht und eine Beleidigung des Andenkens an meinen Stamm.\n\nMacht mich stolz, indem Ihr diese heldenhafte Aufgabe erledigt, dann soll es Euer Schaden nicht sein.", objectives = "Zerstört den Flugapparat bei Beal Modan und kehrt dann zu Gann Stonespire zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[850] = { title = "Anführer der Kolkar", description = "Die Zentauren haben die Tauren seit Jahren geplagt. Die Kolkarzentauren des Brachlandes sind seit kurzem zu einer echten Bedrohung geworden. Normalerweise sind sie in diesen Landen eher unorganisiert, aber es haben sich unter ihnen neue Anführer erhoben. Sie sammeln sich.\n\nWir müssen diese Zentaurenanführer vernichten, um unsere Position hier zu bewahren.\n\nBringt mir den Kopf von Barak Kodobann. Er lagert in der Nähe der vergessenen Teiche im Norden.\n\nBesiegt ihn und kehrt dann zu mir zurück.", objectives = "Bringt Regthar Deathgate westlich von Crossroads Baraks Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[851] = { title = "Verog der Derwisch", description = "Der Zentaur Verog der Derwisch durchwandert das Brachland und wird daher schwer auffindbar sein. Er hat jedoch ein Zentaurenkommandozelt bei der brackigen Oase im Südosten. Vielleicht könnt Ihr ihn zu Euch locken.\n\nReist zur brackigen Oase im Südosten und greift Zentauren in der Nähe des Kommandozeltes an. Es wird gefährlich werden, aber wenn Ihr genug Zentauren tötet, werden sie Alarm schlagen. Und Verog wird kommen.\n\nBringt mir seinen Kopf, dann lege ich ihn neben den von Barak Kodobann.", objectives = "Bringt Regthar Deathgate westlich von Crossroads Verogs Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[852] = { title = "Hezrul Blutmal", description = "Hezrul Blutmal ist der Anführer der Kolkarzentauren im Brachland. Er ist wild, brutal und schlau. Könnte man ihn besiegen, würde das die Kolkars spalten und zerschlagen und die Bedrohung durch sie enorm entschärfen.\n\nAlso tötet ihn. Und bringt mir genau wie zuvor bei Barak und Verog Hezruls Kopf.\n\nEr führt sein Volk von der blühenden Oase im Süden aus an.", objectives = "Bringt Regthar Deathgate westlich von Crossroads Hezruls Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[853] = { title = "Apothekerin Zamah", description = "Ich habe die Sporen, die Ihr mir gabt, zu einer Emulsion verarbeitet. Die muss ich jetzt meiner Kollegin schicken, der Apothekerin Zamah. Wenn Ihr sie ihr bringen könntet, würde sie Euch bestimmt etwas aus ihrem Vorrat alchimistischer Waren anbieten.\n\nSie lebt bei den Teichen der Visionen in einer Höhle unter den Schamanen von Thunder Bluff. Der Pfad zu dieser Höhle ist gut versteckt, aber Ihr könnt ihn am Steilhang der Anhöhe der Geister finden.\n\nBeeilt Euch. Die Emulsion verliert nach einer Weile ihre Wirksamkeit und muss vorher luftdicht verschlossen und weiterverarbeitet sein.", objectives = "Bringt der Apothekerin Zamah in Thunder Bluff die weiterverarbeiteten Sporen, bevor die Zeit abgelaufen ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[854] = { title = "Reise nach Crossroads", description = "Ich habe Eure Ankunft vorausgesehen, junger $C. Aber vielleicht seid Ihr ja gar nicht mehr so jung.\n\nIch glaube, dass es an der Zeit ist, dass Ihr Euch tiefer in dieses Land vorwagt. Ich fühle, dass Ihr zu Größerem berufen seid.\n\nCrossroads wartet auf Euch, denn die Orcs, mit denen wir eng verbunden sind, brauchen Unterstützung. Folgt dieser Straße weiter nach Osten und dann weiter nach Norden bis nach Crossroads. Sucht Thork in seinen Mauern, er hat den Segen der Erdenmutter.", objectives = "Sprecht mit Thork in Crossroads im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[855] = { title = "Zentaurenarmschienen", description = "Die Kolkar sind eine echte Bedrohung für die Besitzansprüche der Horde im Brachland und wir müssen deren Truppen unbedingt dezimieren. Deshalb habe ich eine lohnenswerte Aufgabe für Euch.\n\nErschlagt ihre Krieger, während Ihr Euch auf dem Territorium der Kolkar befindet, und sammelt Zentaurenarmschienen ein. Kommt zurück, wenn Ihr eine ordentliche Menge Armschienen beisammen habt, dann wird Euch die Horde reich belohnen.", objectives = "Bringt Regthar Deathgate westlich von Crossroads 15 Zentaurenarmschienen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[857] = { title = "Die Träne der Monde", description = "Ich hatte die Macht! In diesen meinen Händen! Und ich möchte sie wiederhaben! Wiederhaben möchte ich sie!\n\nDiese dreckigen Ausgräber haben sie entdeckt... sie war so wunderschön. Die Träne der Monde war die erste größere Entdeckung, die wir in Bael Modan gemacht haben.\n\nSie hätte mir gehören sollen! Mir!\n\nGeneral Twinbraid war eifersüchtig auf die Macht, die sie mir verlieh; er sperrte sie weg, in der Burg. Sagte, sie sei verflucht! Dieser Dummkopf!\n\nAndere wollten sie auch haben und sie mussten daran gehindert werden! Dieser Bastard Twinbraid jagte mich weg.\n\nJetzt möchte ich sie wiederhaben. Wiederhaben möchte ich sie!", objectives = "Feegly der Verbannte möchte, dass Ihr ihm die Träne der Monde zurückbringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[858] = { title = "Zündung", description = "Euch hat nicht etwa Sputtervale geschickt? Ich stecke hier in der Klemme. Ich bin hier reingesprungen, ohne daran zu denken, dass ich einen Schlüssel brauche, um die Antriebswelle des Schredders aufzuschließen. Einer der anderen Schredderbediener fragte mich, ob alles in Ordnung sei, und da bin ich in Panik geraten! Statt ihm zu sagen, dass ich meinen Schlüssel nicht dabei hatte, sagte ich ihm, dass es irgendeine mechanische Störung gäbe.\n\nWir müssen hier weg, und zwar schnellstens! Geht hinauf zum Kontrollraum oben auf dem Kran, der Vorsteher sollte einen Schlüssel für diesen Schredder haben.\n\nHelft mir hier raus!", objectives = "Holt den Zündschlüssel und bringt ihn Wizzlecrank.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[860] = { title = "Sergra Dunkeldorn", description = "Wenn Ihr den Pfad der Jäger beschreiten möchtet, dann führt Euch Eure Reise ins Brachland. Die dortigen Wildtiere sind willensstark und unglaublich wild. Ihr werdet beim Jagen dort viel lernen und Euer Geist wird sich entfalten.\n\nSprecht mit Sergra Darkthorn. Sie wird im Brachland Eure Führerin sein.\n\nSergra ist in Crossroads zu finden. Um zu ihr zu gelangen, müsst Ihr von Bloodhoof aus gen Osten ins Brachland reisen und dann an der Weggabelung nach Norden abbiegen. Und seid vorsichtig auf dieser Reise - das Brachland hält für die Unvorbereiteten und Unachtsamen große Gefahren bereit.", objectives = "Sprecht in Crossroads mit Sergra Darkthorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[861] = { title = "Der Weg der Jäger", description = "Euch hat das Jagdfieber gepackt, wie ich sehe. Auch ich war einst wanderlustig...\n\nWollte wandern und jagen. Denn die Jagd ist die größte Ehre für einen Tauren.\n\nWenn Ihr ernsthaft das Leben eines Jägers führen wollt, dann wird Euch Melor Stonehoof den Weg weisen. Er lebt in Thunder Bluff auf der Anhöhe der Jäger.\n\nBringt ihm die Klauen der Flachlandstreuner von Mulgore, um ihm Eure Fertigkeit und Eure Entschlossenheit zu beweisen. Sie sind zäh und schlau - angemessene Beute für einen wie Euch, $C, der so jung wie Ihr auf dem Pfad der Jäger wandeln möchte.", objectives = "Bringt Melor Stonehoof in Thunder Bluff 4 Flachlandstreunerklauen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[862] = { title = "Grubenratteneintopf", description = "Ein $C wie Ihr muss hier im Brachland doch ziemlich hungrig sein. Ich bin den ganzen Tag am Verhungern.\n\nIch sag Euch was, ich bereite Euch einen feinen Eintopf zu. Ich brauche nur ein paar Grubenratten.\n\nScheint so, als würden diese dreckigen Zwerge in Bael Modan von unser aller Lieblingsspeise überrannt. Also reist gen Süden nach Bael Modan und bringt mir ein paar Grubenratten.\n\nIhr dürft Euch erst einen erfahrenen Abenteurer nennen, wenn Ihr Euch ein bisschen mit der Rattenjagd beschäftigt habt! Ha!", objectives = "Bringt Grub östlich von Crossroads 8 Grubenratten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[863] = { title = "Die Flucht", description = "Ich würde mal sagen, ich kann das nach und nach lernen... Kann ja nicht so schwer sein. Ein paar Knöpfchen hier, ein oder zwei Hebelchen da... Also, seid Ihr bereit zu gehen?", objectives = "Schützt Wizzlecrank und den gestohlenen Goblinschredder auf dem Weg zu Sputtervalve in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[864] = { title = "Kehrt zu Apothekerin Zinge zurück", description = "\"Wir sind so weit, die Kraftquelle ist entfernt und die Daten sind gesichert. Also dann, sichere Reisen und all das. Ich hoffe, das ruchlose Wissenschaftsexperiment hat sich für Euch ausgezahlt.\"\n\nDer Goblin wendet sich von Euch ab, um sich den Belangen der Gadgetzan Water Company zu widmen. Ihr verstaut das versiegelte Testset sicher für die Reise zurück nach Undercity. Dort wartet Apothekerin Zinge auf Euch und das versiegelte Feldtestset.", objectives = "Bringt das versiegelte Feldtestset nach Undercity zu Apothekerin Zinge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[865] = { title = "Raptorhörner", description = "Die Raptoren des Brachlandes sind intelligenter als die Raptoren anderer Länder. Und ich glaube, dass ihre ganze Intelligenz in ihren Hörnern sitzt! Wenn dem so ist, könnte ich ihre Hörner zu Pulver zermahlen und benutzen, um \"Klugheitstränke\" zu kreieren. Dafür würde ich ein Vermögen bekommen!\n\nUnd Ihr könntet mir helfen; sucht und bringt mir intakte Raptorhörner von Bluthornsensenklauen. Sie durchstreifen den Süden sowie den Norden des Brachlandes an der Grenze zum Wald von Ashenvale.", objectives = "Sammelt 5 intakte Raptorhörner von Bluthornsensenklauen und bringt sie Mebok Mizzyrix in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[866] = { title = "Wurzelproben", description = "Die Kräuter des Brachlandes sind anders als Kräuter anderer Länder. Ihre Eigenschaften sind zwar fast dieselben, aber das Oasenwasser hier verändert die Pflanzen; sie sind ein klein bisschen anders.\n\nIch möchte diese Unterschiede studieren... um zu sehen, ob man daraus nicht Kapital schlagen kann!\n\nFalls Ihr in der Kräuterkunde bewandert seid, sammelt doch ein paar Wurzelproben der Kräuter, die Ihr im Brachland findet. Bringt mir diese Proben, damit ich sie mit Kräutern aus anderen Regionen vergleichen kann.", objectives = "Bringt Mebok Mizzyrix in Ratchet 8 Wurzelproben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[867] = { title = "Räuberische Harpyien", description = "Die verdammten Harpyien haben unsere Karawanen lang genug geplündert; es ist an der Zeit, dass wir einigen von ihnen die Hälse abschneiden und ihre Anzahl verkleinern.\n\nIch hab mich bei ihren Nestern mal ein bisschen umgeschaut und herausgefunden, wer da wen anführt. Der vernichtendste Angriff wird einen guten Teil ihrer niederen Befehlskette zerstören und dann können wir uns bis zur Spitze vorarbeiten.\n\nWir fangen langsam an; schaltet die Harpyien der Hexenschwingen und Wildfedern der Hexenschwingen im Nordwesten aus und bringt mir 8 Krallen der Hexenschwingen. Das sollte ein guter Anfang sein...", objectives = "Sammelt 8 Krallen der Hexenschwingen.\n\nBringt sie Darsok Swiftdagger in Crossroads.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[868] = { title = "Eierjagd", description = "He, $N. Man hat mich nach Crossroads geschickt, damit ich über das Land wache und meinen Meistern in Orgrimmar über eventuelle Vorkommnisse berichte.\n\nEines meiner Studienobjekte sind die insektenartigen Kreaturen, die man im Süden auf dem Feld der Riesen findet. Wir wissen nur wenig über diese Kreaturen, also haben wir es uns zur Aufgabe gemacht, mehr über sie zu erfahren. Sie scheinen intelligent zu sein, intelligenter als normale Tiere.\n\nNehmt diese Grabgabel und grabt ein paar ihrer Eier aus den Hügeln aus, aber seid vorsichtig: einmal aufgeschreckt, werden sie Euch angreifen.", objectives = "Bringt Korran in Crossroads 12 Silithideneier und die Grabgabel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[869] = { title = "Raptorendiebe", description = "Vor kurzem wurde eine Ladung Silber aus unserem Wachturm entwendet. Sie war als Sold für die Crossroads-Wachen gedacht und wir wollen das Silber zurückhaben.\n\nDas Seltsamste daran ist... wir haben einen der Diebe in der Nacht des Raubes erwischt. Und... es war ein Raptor! Unglaublich!\n\nIch weiß nicht, wofür Raptoren Silber brauchen könnten. Aber das ist mir auch egal - ich will die Raptoren tot sehen, damit sie uns nicht wieder bestehlen!\n\nJagt Raptoren im Brachland. Sammelt ihre Köpfe für mich!", objectives = "Bringt Gazrog in Crossroads 12 Raptorenköpfe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[870] = { title = "Die Vergessenen Teiche", description = "Vor langer Zeit war das Brachland ein üppiger Ort voller Leben. Aber Krieg und Katastrophen verheerten das Land, verbrannten es und jetzt ist es nur noch eine ausgedörrte Hülse. So ist es nun einmal und es macht mich traurig.\n\nIn den letzten Jahren jedoch sind Oasen im Brachland entstanden und das Leben blüht wieder auf. Und wir Druiden spüren eine Macht von ganz tief unten an die Oberfläche dringen.\n\nWir müssen ihre Quelle finden. Reist zu den vergessenen Teichen nordwestlich von Crossroads. Sucht in den dortigen Gewässern nach einer Quelle der Macht und kommt dann hierher zurück.", objectives = "Berichtet Tonga Runetotem von Euren Entdeckungen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[871] = { title = "Vereitelung der Angriffe", description = "Alle Stacheleber sind unsere Feinde, $N. Manche sind nur lästiger als andere.\n\nDer Grimmhauerstamm hat unsere Nachschublinien von Durotar aus angegriffen, was uns nicht wenig Ärger bereitet. Ich habe Späher ausgeschickt, um den Anführer dieser Überfälle zu finden, aber bis es so weit ist, könnte es uns schon helfen, wenn Ihr diese dreckigen Schweinemenschen etwas dezimieren würdet.\n\nBeginnt im Nordosten in Richtung Durotar. Ihr könnt ihre Baue immer an den riesigen, dornigen Ranken erkennen, die aus dem Boden wachsen. Sucht sie und erschlagt sie.", objectives = "Tötet 8 Wassersucher, 8 Dornwirker sowie 3 Jäger des Grimmhauerstamms und kehrt dann zu Thork in Crossroads zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[872] = { title = "Das Ende der Unterbrechungen", description = "Einer meiner Späher war Zeuge eines Angriffs auf eine Karawane aus Durotar, $N. Die Übeltäter waren in der Tat vom Grimmhauerstamm der Stacheleber. Ein ganz bestimmter Stacheleber führte den Überfall an: Kreenig Grantelschnauze. Man hat ihn nordöstlich von hier gesehen, gleich südlich der Straße von Durotar. Wenn diese Bedrohung jemals ein Ende finden soll, dann muss Kreenig sterben.\n\nDamit diese Angriffe auch wirklich aufhören, würde ich sagen, dass wir das Ganze auf die Spitze treiben sollten. Tötet Kreenig und andere seines Stammes und kehrt dann zu mir zurück, wenn Ihr seine Hauer habt.", objectives = "Tötet 8 Geomanten der Grimmhauer, 8 Verteidiger der Grimmhauer und Kreenig Grantelschnauze.\n\nBringt dann Thork in Crossroads Kreenig Grantelschnauzes Hauer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[873] = { title = "Isha Awak", description = "Isha Awak ist der Herr über diese Gewässer. Groß ist seine Kraft und edel sein Stolz. Die Menschen an der Küste fürchten ihn, denn er hat großen Schaden unter ihnen angerichtet.\n\nIch jedoch fürchte ihn nicht. Ich bin froh, dass er hier ist. Er ist eine würdige Herausforderung und eine ehrenhafte Beute.\n\nWenn Ihr bereit seid, schwimmt hinaus und sucht nach Isha Awak, der Tiefsten Verdammnis.\n\nSein Geist wohnt in seinem Herzen, und dieses schlagen zu hören heißt, Euer Schicksal zu kennen.", objectives = "Bringt Mahren Skyseer das Herz von Isha Awak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[874] = { title = "Mahren Himmelsdeuter", description = "Ihr habt die Wildtiere des Brachlandes gejagt. Euer Geist ist stark. Ein Jäger muss jedoch immer vorbereitet sein. Ein wahrer Jäger kann auf allen Pfaden seine Beute finden. Weder Berg noch Sumpf wird ihn wanken lassen.\n\nNicht einmal das Meer.\n\nSucht meine Schwester Mahren. Sie jagt die großen Wassertiere entlang der Küste. Sie wird Euch etwas über sie lehren.\n\nSeid jedoch vorsichtig, während Ihr nach ihr sucht, denn die Küste des Brachlandes ist in den Händen der Menschen.", objectives = "Sprecht mit Mahren Skyseer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[875] = { title = "Offiziere der Harpyien", description = "Hahaha, $N. Ihr wollt noch mehr? Gut, das hör ich gern.\n\nDieses Mal möchte ich, dass Ihr ein paar der Offiziere der Harpyien in den trockenen Hügeln meuchelt. Nur Töter der Hexenschwingen können Offiziere werden und Ihr erkennt sie an den Ringen, die sie tragen. Sie sind ein übler Haufen, aber sie führen ein paar der Unterlinge in diesem Gebiet an. Schaltet Ihr 6 davon aus, wird das ein Entscheidungsschlag gegen ihr Matriarchat sein.\n\nSorgt dafür, dass sie schmerzvoll sterben, $n. Wir möchten, dass diese Dirnen von Harpyien lernen, wie wahnwitzig es ist, sich mit der Horde anzulegen.", objectives = "Sammelt 6 Harpyienoffiziersringe von den Tötern der Hexenschwingen und kehrt dann zu Darsok Swiftdagger in Crossroads zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[876] = { title = "Serena Blutfeder", description = "Ihr habt das mit den Offizieren und Unterlingen so gut erledigt, dass ich Euch noch um einen letzten Dienst bitten möchte.\n\nSerena Blutfeder ist die Schwester einer Harpyie namens Blutfeder, die Rexxar vor einer ganzen Weile erschlug. Offensichtlich wurden die Karawanen der Horde angegriffen, um ihre Schwester zu rächen.\n\nIch möchte, dass Ihr ihr die Kehle durchschneidet und mir ihren Kopf bringt. Er soll die nächste Karawane schmücken, die wir losschicken... Gebt diesen Harpyien etwas, über das sie nachdenken können.", objectives = "Erschlagt Serena Blutfeder und bringt Darsok Swiftdagger in Crossroads ihren Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[877] = { title = "Die Brackige Oase", description = "Erdrisse wie jene, die Ihr bei den vergessenen Teichen gefunden habt, könnte es auch bei anderen Oasen im Brachland geben. Wenn es so ist, sind diese Risse vielleicht die Lebensquelle dieser Oasen.\n\nWir müssen das überprüfen.\n\nHier, nehmt diese Samen. Sie sind tot und unfruchtbar, aber bringt sie dennoch zur brackigen Oase im Südosten. Falls es dort einen Riss gibt, legt die Samen hinein und ... wartet ab.", objectives = "Kehrt zu Tonga in Crossroads zurück, nachdem Ihr die brackige Oase untersucht habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[878] = { title = "Stämme im Krieg", description = "Ihr müsst meine Feinde schlagen. <schnaubt> Ihr müsst Quetschzahn und dem Grimmhauerstamm helfen, indem Ihr die Borstennacken schwächt. Beide Stämme sind sehr spirituell - gebunden an die Erde und ihre Kraft. <schnaubt> Sie gibt uns Stärke in allen Dingen... besonders im Krieg.\n\nWenn ihr herausfinden wollt, wer Thork <schnaubt> und der Horde wirklich solche Angst bereitet, dann helft Quetschzahn! Ihr greift die spirituellen Anführer der Borstennacken im Norden an und schwächt sie, sodass die Grimmhauer sie besiegen und das Brachland beherrschen können.", objectives = "Erledigt 6 Wassersucher der Borstennacken, 12 Dornenwirker der Borstennacken sowie 12 Geomanten der Borstennacken und kehrt zu Quetschzahn im Camp Taurajo im Brachland zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[879] = { title = "Verräter in den eigenen Reihen", description = "Drei meines Stammes kamen aus dem Kral, um die Überfälle gegen die Horde anzuführen, $R. <schnaubt> Sie sind ruchlos und schlau und wenn Ihr sie besiegt, dann werden Crossroads und auch der Großteil des Brachlandes Frieden haben... <schnaubt> zumindest vor dem Grimmhauerstamm. <schnaubt>\n\nSucht nach Nak, Kuz und Lok Orcbane. Sie befinden sich weit im Süden des Brachlandes. Einer ist ein Zauberer, ein weiterer ein Fährtenleser und ihr Anführer, den sie Orcbane nennen, <schnaubt> ist ein Krieger. Tötet sie, $R, so wie sie mich töteten.", objectives = "Tötet Nak, Kuz und Lok Orcbane und bringt Quetschzahn im Camp Taurajo im Brachland ihre Schädel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[880] = { title = "Veränderte Wesen", description = "Eure Entdeckungen sind erstaunlich, $N. Diese Oasen haben Eigenschaften, die von einer Quelle außerhalb stammen müssen. Oder vielleicht von einer inwärtigen.\n\nIch muss wissen, auf welche Weise diese Felsspalten die Wildtiere beeinflussen, die vom Wasser der Oasen trinken.\n\nJagt Oasen-Schnappkiefer in der blühenden Oase und der brackigen Oase. Bringt mir ihre Schalen, damit ich sie untersuchen kann.", objectives = "Bringt Tonga Runetotem in Crossroads 8 veränderte Schnappkieferschalen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[881] = { title = "Echeyakee", description = "Whitemist, Echeyakee in der Sprache der Tauren, ist der König der Savannenkatzen. Er jagt mit solcher Verstohlenheit, dass man sagt, er sei wie ein dünner, weißer Nebel auf der Erde. Und er tötet so schnell, dass seine Beute weder Angst noch Schmerz verspürt.\n\nDie Tauren sagen, er sei sowohl Gnade als auch Tod.\n\nIhr werdet erfahren, ob das wahr ist, denn ich schicke Euch aus, um Echeyakee zu jagen. Sein Unterschlupf befindet sich im Nordosten von Crossroads, zwischen den Knochen des riesigen Kodos.\n\nGeht jetzt. Blast dieses Horn, wenn Ihr seinen Unterschlupf erreicht. Blast das Horn und er wird kommen.", objectives = "Bringt Sergra Darkthorn in Crossroads Echeyakees Balg.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[882] = { title = "Ishamuhale", description = "Ishamuhale - Speerzahn - ist der wildeste Bluthornraptor des Brachlandes. Er jagt weder zum Spaß noch für Nahrung. Er jagt, weil Jagen seine Leidenschaft ist. Er tötet, weil Töten seine Natur ist.\n\nUnd Ihr werdet Euch mit seiner Natur vertraut machen, $N, denn Euer Weg folgt jetzt den Krallenspuren Ishamuhales.\n\nBeginnt mit der Jagd. Erlegt seine Lieblingsbeute, ein Zhevra, und bringt den Kadaver zum toten Baum im Nordwesten von Ratchet. Ishamuhale wird den Kadaver riechen und von ihm angezogen werden.\n\nSeid bereit, wenn er kommt.", objectives = "Bringt Jorn Skyseer im Camp Taurajo Ishamuhales Fangzahn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[883] = { title = "Lakota'mani", description = "Lakota'manis Huf ist ein Symbol für die Kraft der großen Kodos.", objectives = "Bringt Jorn Skyseer im Camp Taurajo Lakota'manis Huf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[884] = { title = "Owatanka", description = "Wenn man Owatankas Schwanzstachel berührt, stieben Funken auf.", objectives = "Bringt Jorn Skyseer im Camp Taurajo Owatankas Schwanzstachel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[885] = { title = "Washte Pawne", description = "Eine Berührung mit der Feder von Washte Pawne ist schmerzhaft.", objectives = "Bringt Jorn Skyseer im Camp Taurajo Washte Pawnes Feder.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[886] = { title = "Die Oasen des Brachlandes", description = "Die Druiden von Thunder Bluff spüren eine große Macht, die östlich von Mulgore ins Brachland sickert.\n\nTonga Runetotem wurde entsandt, um die Quelle dieser Macht ausfindig zu machen, aber wir befürchten, dass er Hilfe brauchen wird.\n\nReist ins Brachland und sprecht mit Tonga. Er wird in Crossroads sein. Um dorthin zu gelangen, folgt der Straße von Bloodhoof aus nach Osten. Betretet das Brachland und wendet Euch bei der Weggabelung weiter nach Norden. Geht weiter Richtung Norden, dann gelangt Ihr nach Crossroads.\n\nUnd haltet Euch immer auf der Straße, $N, denn das Brachland ist ein raues Land.", objectives = "Sprecht in Crossroads mit Tonga Runetotem.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[887] = { title = "Südmeerfreibeuter", description = "Ich wünschte, Vize-Admiral Grezzlik würde bessere Arbeit bei der Sicherung der Meere für unsere Handelsschiffe leisten. Bei all dem Gold, das die Handelsbarone in die Handelsflotten gesteckt haben, macht es mich rasend zu sehen, wie viele Piraten unbehelligt unterwegs sind, meine Schiffe überfallen und meine Waren stehlen!\n\nMir kam zu Ohren, dass die Südmeerfreibeuter südlich von hier ein Lager aufgeschlagen haben. Sie sind mir ein echter Dorn im Auge, und wenn sich Grezzlik nicht um sie kümmert, könnt Ihr mir vielleicht helfen, sie loszuwerden?", objectives = "Tötet für Gazlowe in Ratchet 12 Briganten der Südmeerfreibeuter und 6 Kanoniere der Südmeerfreibeuter.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[888] = { title = "Gestohlene Beute", description = "Ich hätte zwar gern, dass Ihr mir all meine Waren zurückbringt, aber das dürfte wohl unmöglich sein. Es gibt jedoch ein paar Dinge, die ich unbedingt wiederhaben muss!\n\nWie Ihr seht, ist mein Observatorium fast einsatzbereit, aber es fehlt noch die kleinere der zwei Linsen. Die erste Linse ist mit der Karawane aus Durotar gekommen, aber die zweite wurde per Schiff verschickt und ist nie hier eingetroffen. Ebenso ist meine Stiefellieferung von Drizzlik aus Booty Bay nicht hier angekommen!\n\nBegebt Euch zum Piratenlager und seht mal nach, ob Ihr die Dinge dort finden könnt.", objectives = "Bringt Gazlowe in Ratchet die Stiefellieferung und die Teleskoplinse zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[889] = { title = "Geist des Windes", description = "Wenn die Ranken aus der Erde brechen, treten oftmals auch Mineralvorkommen an die Oberfläche.\n\nEin ganz spezielles Mineral, das in der Nähe der Ranken zu finden ist, heißt Bluterz; der Borstennackenstamm glaubt, das Bluterz sei heilig und ein Teil von Agammagans Körper. Sie tragen manchmal Splitter davon als Glücksbringer bei sich.\n\nIch glaube, ich könnte aus diesem Erz eine neue Legierung herstellen, wenn ich genug davon hätte. Sucht südlich von hier auf der anderen Seite des ausgetrockneten Flussbetts nach Stammesmitgliedern der Borstennacken und bringt mir so viele Blutsplitter, wie Ihr könnt.", objectives = "Bringt Tatternack Steelforge in Crossroads 20 Blutsplitter.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[890] = { title = "Die verloren gegangene Lieferung", description = "Ich warte schon eine Ewigkeit auf meine letzte Warenlieferung aus Booty Bay! Ich bin mir ziemlich sicher, dass die Seeräuber sie gestohlen haben; würdet Ihr wohl, nur um sicher zu sein, zu den Docks gehen und Dizzywig fragen, ob meine Waren vielleicht ohne mein Wissen bereits ins Lagerhaus gebracht wurden?\n\nHier, nehmt mein Geschäftsbuch mit zu Dizzywig, damit er meine Inventaraufzeichnungen mit seinen Büchern gegenprüft.", objectives = "Bringt Werftmeister Dizzywig Gazlowes Geschäftsbuch.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[891] = { title = "Die Kanonen von Northwatch", description = "Wieder ist ein Schiff meiner Flotte diesen übereifrigen Menschen der Feste Northwatch in die Hände gefallen!\n\nMan muss sich um diese Bastarde kümmern. Ihr Verfolgungswahn hat sie in eine Art Raserei versetzt. Diese schießwütigen, rücksichtslosen Rüpel schießen auf alles, was sich bewegt.\n\nReist gen Süden entlang der Händlerküste zur Feste und belagert ihre Streitkräfte. Bringt mir die Medaillen ihrer Soldaten als Beweis. Und erschlagt um meiner Flotte willen Captain Hellstieg und ihre übereifrigen Kanoniere!", objectives = "Kapitän Thalo'thas Brightsun aus Ratchet möchte, dass Ihr 10 Medaillen von Theramore sammelt und Captain Hellstieg, Kanonier Knoch und Kanonier Hecksler tötet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[892] = { title = "Die verloren gegangene Lieferung", description = "Laut meinen Aufzeichnungen ist alles in Ordnung, $n. Geht zurück und sagt Gazlowe, dass er wohl Pech gehabt hat. Es würde mich nicht überraschen, wenn sich die Piraten seine Waren geschnappt hätten.\n\nIch kann leider nicht mehr für ihn tun. Oh... Ihr könnt ihm allerdings sagen, dass ich ein paar Dinge aus Undermine für ihn habe, falls er die Zeit findet, sie abzuholen.", objectives = "Bringt Gazlowe in Ratchet sein Geschäftsbuch zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[893] = { title = "Ausgewählte Waffen", description = "Die Stacheleber des Grimmhauerstamms im Süden, hinter dem Feld der Riesen, haben keine erfahrenen Schmiede, soweit ich weiß, aber Sie haben anscheinend begonnen, stabilere Waffen zu entwickeln. Ich hätte gern ein paar verschiedene Arten davon, um etwas über ihre Techniken zu erfahren, so möglich.\n\nWenn Ihr der Horde Ehre bringen wollt, dann bringt mir Exemplare von ihren Waffen. Besorgt mir einen Dolch von ihren Schleichern, einen Zauberstab von ihren Sehern und einen Schild von ihren Kriegsberserkern. Das sollte reichen!", objectives = "Bringt Tatternack Steelforge im Camp Taurajo im Brachland einen Grimmhauerrückenstecher, einen verkohlten Grimmhauerzauberstab und einen Grimmhauerkriegsschild.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[894] = { title = "Samophlang", description = "Die Venture Company hat weit nördlich von hier, südwestlich des Schlickermoores, eine kleine Forschungseinrichtung errichtet. Was die Leute dort tun, weiß ich nicht genau, aber ich habe herausgefunden, dass sie dort mit etwas experimentieren, das 'Samophlang' genannt wird.\n\nWas zum Teufel ist ein Samophlang? Na ja, was immer es auch ist, ich möchte es untersuchen, also brauche ich jemanden, der eines beschafft.\n\nIch habe ein Exemplar der Bedienungsanleitung für ihr Steuersystem in die Finger bekommen; Ihr solltet also herausfinden können, wie man das Samophlang daraus entfernt.", objectives = "Verschafft Euch Zugang zur Steuerkonsole in der Forschungseinrichtung der Venture Company.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[895] = { title = "GESUCHT: Baron Küstenschipper", description = "GESUCHT!\n\nBaron Küstenschipper, Kapitän der GNADENLOS\n\nCaptain Küstenschipper aus Gilneas befehligt Schiffe der Südmeerfreibeuter und wird wegen Piraterie gesucht. Seine Überreste müssen in noch erkennbarem Zustand sein!\n\n- Gazlowe", objectives = "Bringt Gazlowe in Ratchet Baron Küstenschippers Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[896] = { title = "Des Minenarbeiters Vermögen", description = "Als Werftmeister eines so geschäftigen Hafens wie Ratchet habe ich mein Ohr immer am Puls der Zeit. Ich weiß alles über den Verkehr von Waren und Geld zwischen hier und Booty Bay.\n\nDie jüngste Neuigkeit, die ich erfahren habe, betrifft die Felsadermine der Venture Company nordöstlich des Schlickermoores. Einer der Minenarbeiter hat dort einen faustgroßen Smaragd gefunden. Ich kenne ein paar Käufer, die sich die Finger nach so etwas ablecken würden... und ich würde bei einem Verkauf Halbe-Halbe machen.", objectives = "Beschafft Euch von einem der Vorarbeiter oder Vollstrecker der Venture Company den Katzenaugensmaragd und bringt ihn zu Dizzywig in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[897] = { title = "Der Ernter", description = "Diese seltsame, insektenartige Kreatur scheint außerhalb der natürlichen Ordnung zu stehen, so als würde sie nicht ins Brachland gehören.", objectives = "Bringt den Ernterkopf zu Jorn Skyseer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[898] = { title = "Aus der Gefangenschaft befreit", description = "Endlich! Jemand rettet mich!\n\nIch kann es nicht glauben, dass Ihr an den Wachen vorbeigekommen seid. Diese Fanatiker aus Theramore müssen verrückt sein. Sie haben unser Schiff versenkt und mich, den einzigen Überlebenden, eingesperrt. Sie nannten mich ihren Feind und eine Gefahr für die Allianz.\n\nIch! Eine Gefahr für diesen Riesenschwindel, den sie Allianz nennen? Ich war Decksmann auf einem Fuseltransporter zwischen Ratchet und Booty Bay.\n\nGenug geredet. Helft Ihr mir, zurückzukommen nach Ratchet, ja? Lasst es mich wissen, wenn Ihr bereit seid, hier auszubrechen.", objectives = "Begleitet Gilthares Firebough sicher zurück zu Kapitän Brightsun in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[899] = { title = "Von Hass zerfressen", description = "Vielleicht kennt Ihr diesen Schmerz der Ungewissheit, $C, vielleicht auch nicht. Doch wisset: Ich stehe hier jeden Tag, vom Aufgang der Sonne bis zu ihrem Untergang, und suche den Horizont nach diesen Monstern ab. Ich habe jeden Schweinemenschen getötet, den ich seitdem gesehen habe, doch der Durst nach ihrem Blut ist noch lange nicht gestillt. Vielleicht hätte ich mich nach Taurajo begeben sollen, statt nördlich nach Crossroads.\n\nIhr, $C, könntet mir helfen.\n\nTötet sie. Tötet so viele Ihr könnt und bringt mir ihre Hauer, dann werden wir ihren Tod miteinander feiern.", objectives = "Bringt Mankrik in Crossroads 60 Stacheleberhauer der Borstennacken.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[900] = { title = "Samophlang", description = "Die drei Steuerventile sind momentan geöffnet. Die verschiedenen Anzeigen der Steuerkonsole führen Euch zu der Annahme, dass man sie zunächst schließen muss, bevor der Apparat ausgeschaltet werden kann.", objectives = "Schließt das Treibstoffzufuhrventil, das Regelventil und das Hauptsteuerventil, und benutzt dann noch einmal die Steuerkonsole.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[901] = { title = "Samophlang", description = "Da der Apparat jetzt ausgeschaltet ist, kann die Steuerkonsole geöffnet und das Samophlang entfernt werden. Alles andere sollte unangetastet bleiben und Ihr benötigt jetzt nur noch den Schlüssel, mit dem die Konsole geöffnet werden kann.", objectives = "Besorgt Euch bei Tüftler Sniggles den Konsolenschlüssel, um damit die Steuerkonsole zu öffnen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[902] = { title = "Samophlang", description = "Nach dem Öffnen der Front der Steuerkonsole zeigt sich ein dichtes Gewirr aus Kabeln, Schläuchen und anderen seltsamen, mechanischen Objekten - die meisten davon scheinen keinen praktischen Nutzen zu haben. Ihr schiebt sie beiseite und arbeitet Euch tiefer in die Konsole vor, bis Ihr schließlich das Samophlang gefunden habt. Mit einem Ruck zieht Ihr es aus der Halterung.", objectives = "Bringt das Samophlang zu Sputtervalve in Ratchet.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[903] = { title = "Streuner des Brachlandes", description = "Es ist nun an der Zeit, etwas zu jagen, das sich wirklich wehrt. Die Streuner des Brachlandes sind von zäher Art. Zäh, erfinderisch, listig... und tödlich. Ihr findet sie zwischen den hohen Gräsern. Ihr werdet viele südwestlich von Crossroads finden.\n\nSeid vorsichtig, wenn Ihr sie jagt, $n, oder Ihr werdet feststellen, dass Ihr nicht mehr Jäger, sondern Gejagter seid.", objectives = "Besorgt für Sergra Darkthorn in Crossroads 7 Streunerklauen von den Savannenstreunern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[905] = { title = "Die wütenden Sensenklauen", description = "Tja, $N, die Jagd wird schwieriger. Jetzt müsst Ihr Eure Beute besiegen und dann Euren Weg zu ihrem Unterschlupf finden.\n\nJagt die Bluthornraptoren im Süden. Erledigt sie und nehmt Euch die Federn, die sie tragen. Legt die Federn in die Sensenklauennester südwestlich der brackigen Oase. Zeigt ihren Brüdern, dass Ihr sie nicht fürchtet!", objectives = "Tötet Bluthornraptoren und nehmt ihre Federn mit. Benutzt die Federn bei den drei Sensenklauennestern. Kehrt zu Sergra Darkthorn in Crossroads zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[906] = { title = "Verräter in den eigenen Reihen", description = "Bringt Loks Kopf zu Thork in Crossroads, $R. <schnaubt> Er sollte ohne Worte wissen, was meinem Stamm zugestoßen ist - ha, nicht dass er denken würde, Quetschzahn hätte bei <schnaubt> solchen Dingen geholfen. Aber ich bin sicher, er wird Euch für das Ausführen einer solch großen Tat belohnen. <schnaubt>\n\nIch werde Euch auch weiterhin mit Agammagans Macht segnen, solange ich in diesem Käfig verbleibe, $R. Bis dann, lebt wohl.", objectives = "Bringt Loks Kopf zu Thork in Crossroads im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[907] = { title = "Wütende Donnerechsen", description = "Nun denn, $n, jetzt müsst Ihr den großen Donnerechsen gegenübertreten. Diese Bestien sind so groß, dass der Boden erbebt, wenn sie über die Ebenen stampfen. Seid vorsichtig, wenn Ihr gegen sie kämpft, denn ein einziger falscher Schritt, und schon findet Ihr Euch unter ihren Füßen wieder.\n\nIhr findet die Donnerechsen im Südlichen Brachland. Man kennt sie als Sturmschnauzen, Sturmechsen und Donnerköpfe. Kehrt zu mir zurück, nachdem Ihr sie überwältigt habt.", objectives = "Bringt das Blut von 3 Donnerechsen ins Camp Taurajo zu Jorn Skyseer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[910] = { title = "Unten an den Docks", description = "Ich hab' Geschichten gehört von riesigen Schiffen, die zwischen Ratschet und Beutebucht hin- und hersegeln. Es wäre so toll, auf dem Ozean zu segeln und fantastische Seeschlachten erleben zu können. Wenn ich erwachsen bin, werde ich vielleicht auch ein mächtiger Seefahrer der Horde!\n\nKönnt Ihr mir bitte die Docks von Ratschet zeigen? Ich verspreche, auch nicht ins Wasser zu fallen oder Ärger zu machen. Ich will nur einmal die großen Schiffe sehen und das salzige Meerwasser riechen!", objectives = "Bringt Euren Schützling zu den Docks von Ratschet im Brachland.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[911] = { title = "Das Tor zur Grenze", description = "Sie sagen, dass das Eschental das neue Grenzland und der Schutzwall von Mor'shan im Brachland das Tor dorthin wären. Es wäre so toll, ein Pionier zu sein und alles, was man zum Überleben braucht, in der Wildnis zu sammeln! Sie sagen, dass dies der Ort ist, an welchem in Zukunft die Horde und die Allianz ihre Kämpfe austragen werden. Ich möchte unbedingt dahin!\n\nKönnen wir bitte zum Schutzwall von Mor'shan gehen? Ich würde so gerne mal das Grenzland sehen! Ich möchte sehen, wie die Horde diese stinkenden Nachtelfen von dort vertreibt.", objectives = "Begleitet Euren Schützling zum Schutzwall von Mor'shan im nördlichen Teil des Brachlands, kurz bevor man das Eschental betritt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[913] = { title = "Der Ruf des Donnerfalken", description = "Der Donnerfalke, $N, ist eine ungestümes Wildtier. Es ist an der Zeit für Euch, ihm gegenüberzutreten. Ihr müsst herausfinden, wo er umherstreift, und mir seine Flügel als Beweis für Eure erfolgreiche Jagd bringen.\n\nWenn Ihr das tut, wird Eure Zeit mit mir sich ihrem Ende nähern.", objectives = "Sucht und erschlagt einen Donnerfalken und bringt Jorn Skyseer in Taurajo seine Flügel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[914] = { title = "Anführer der Giftzähne", description = "Die Druiden in den Höhlen des Wehklagens, die Druiden des Giftzahns, sind eine Verirrung der Natur. Einst gehörten sie einem Orden edler Druiden an, deren Plan es war, das Brachland zu heilen, doch jetzt trachten sie danach, das Land ihren eigenen verderbten Träumen gleichzumachen.\n\nDie Druiden des Giftzahns haben vier Anführer, und jeder besitzt einen Traumedelstein. Selbst jetzt noch verfolgen mich ihre Gesichter! Besiegt die Anführer und bringt mir ihre Edelsteine, dann wird das Brachland endlich wieder Frieden haben.\n\nGeht, $n. Sie halten sich tief in den Höhlen des Wehklagens verborgen.", objectives = "Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Thunder Bluff zu Nara Wildmane.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[915] = { title = "Lecker Eis", description = "EISCREME! Oh, könnt Ihr mir bitte, bitte, bitte, etwas Eiscreme besorgen? Am liebsten mag ich Erdbeere und es gibt einfach kein besseres Erdbeereis als das von Tigule und Foror. Das ist mein liebstes Eis auf der ganzen Welt!\n\nFrüher gab es das immer auf der Rennstrecke in der Schimmernden Ebene, aber ich habe mal gehört, dass man es jetzt auch in der Stadt kaufen kann. Kriege ich bitte eins? Bitte? Am liebsten Tigules und Forors Eiscreme.", objectives = "Besorgt für Euren Schützling etwas Erdbeereis. Der Kleine scheint die Marke 'Tigules und Forors Eiscreme' zu bevorzugen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[916] = { title = "Waldwebergift", description = "Ich kam nach Shadowglen, um hier die Waldweberspinnen zu beobachten, die in der Schattenweberhöhle leben. Sie sind mit einer wesentlich kleineren Spinnenart verwandt. Ich glaube, der Weltbaum hat einen nicht unerheblichen Effekt auf sie und ich hätte gern ein paar Exemplare von ihnen, um dies zu belegen.\n\nAls Erstes hätte ich gern etwas von ihrem Gift. Sammelt Giftbeutel der Waldweberspinnen, die in und um die Schattenweberhöhle herum zu finden sind. Dann kann ich ihren und das Gift ihrer kleineren Verwandten auf Gemeinsamkeiten hin untersuchen.", objectives = "Bringt Gilshalan Windwalker in Aldrassil 10 Waldwebergiftbeutel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[917] = { title = "Waldweberei", description = "Jetzt, da ich das Spinnengift habe, hätte ich gern auch ein paar lebende Exemplare, um sie zu studieren. Leider kann ich Euch nicht darum bitten, eine lebende Riesenspinne für mich einzufangen, $C. Eine Riesenspinne kann ich allein sowieso nicht bewältigen!\n\nWenn Ihr mir allerdings ein unausgebrütetes Ei besorgen könntet, wäre es viel einfacher, lebende Exemplare zu bekommen, und ich könnte dafür sorgen, dass die noch nicht ausgeschlüpften Exemplare ordentlich unter Verschluss gehalten werden.\n\nTief in der Schattenweberhöhle gibt es angeblich ein Nest. Bitte, beschafft mir ein Ei aus diesem Nest und bringt es mir.", objectives = "Bringt Gilshalan in Aldrassil ein Waldweberei.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[918] = { title = "Bäumlingssamenkörner", description = "Die Bäumlinge von Teldrassil sind Naturelementare. In ihnen spiegelt sich in gewisser Weise die natürliche Ordnung von Flora und Fauna unseres großen Baums wider.\n\nDaher ist es höchst beunruhigend zu sehen, dass die Bäumlinge so wütend geworden sind.\n\nIch glaube, es hat etwas mit dem Erdboden zu tun. Ich habe mich viel mit verschiedenen Düngemethoden für Pflanzen beschäftigt und würde sie gern an Bäumlingssamenkörnern ausprobieren. Würdet Ihr bitte in der Gegend des Al'Amethsees ein paar Bäumlingssamenkörner sammeln und mir bringen?", objectives = "Bringt Denalan am Al'Amethsee 8 Bäumlingssamenkörner.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[919] = { title = "Bäumlingssprossen", description = "Kleine Bäumlinge sprießen rund um das Wasser des Al'Amethsees. Ich fürchte, dass man diesen Schösslingen nicht mehr helfen kann - wir sollten versuchen, sie auszureißen, bevor sie groß genug sind, um Probleme zu bereiten.\n\nWenn Ihr auf Euren Wanderungen um den See Bäumlingssprossen seht, reißt sie bitte aus. Helft dabei, unser Land rein zu halten!", objectives = "Bringt Denalan am Al'Amethsee 12 Bäumlingssprossen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[920] = { title = "Tenarons Einladung", description = "Ihr seid $n, nicht wahr? Ich hörte, dass Tenaron nach Euch gefragt hat. Ihr findet ihn in dem am höchsten gelegenen Raum in Aldrassil.\n\nWir mögen zwar ein langes Leben haben, aber Ihr solltet ihn dennoch nicht allzu lang warten lassen.", objectives = "Sprecht in Shadowglen über den Dächern von Aldrassil mit Tenaron Stormgrip.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[921] = { title = "Krone der Erde", description = "Es ist an der Zeit herauszufinden, was Euer Schicksal ist, $n. Doch bevor Ihr bereit seid, in die Welt hinter unseren verzauberten Wäldern hinauszuziehen, gibt es noch vieles, das Ihr über unsere jüngste Vergangenheit lernen müsst.\n\nSeit der Schlacht am Berg Hyjal hat sich für unser Volk so viel verändert. Nordrassil ist nur noch ein Schatten ihres früheren Selbst, ihre Macht wurde benutzt, um Archimonde in die Knie zu zwingen und die Brennende Legion zurückzutreiben ...\n\nIhr müsst eine Aufgabe erledigen. Geht zum Mondbrunnen nördlich von Aldrassil und bringt mir eine Phiole mit Wasser daraus.", objectives = "Füllt die Kristallphiole und bringt sie Tenaron Stormgrip über den Dächern von Aldrassil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[922] = { title = "Rellian Grünwipfel", description = "$N, würdet Ihr wohl eines der Samenkörner, die Ihr mir besorgt habt, meinem Freund Rellian Greenspyre bringen? Er ist Druide in Darnassus, und bei unserem letzten Gespräch machte er deutlich, dass er an meiner Arbeit mit den Bäumlingen interessiert sei. Er hatte selbst ein paar Ideen und würde sich über ein Exemplar dieser Samenkörner sicherlich freuen.\n\nDanke, $N. Ihr wart mir eine große Hilfe. Ich hoffe, dass ich Euch eines Tages die Früchte meiner Arbeit zeigen kann.\n\nIhr findet Rellian normalerweise die Wege der Enklave des Cenarius in Darnassus entlangwandernd.", objectives = "Bringt Rellian Greenspyre in Darnassus ein Bäumlingssamenkorn.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[923] = { title = "Tumore", description = "Bosheit wuchert in den Bäumlingen. Wir versuchen, die Ursache dafür zu finden, aber bis dahin... Aus Sorge um Teldrassils Sicherheit müssen wir alle Bäumlinge fällen, denen nicht mehr geholfen werden kann. Diejenigen, die die Gegend um den Wellspringsee im Norden von Teldrassil durchstreifen, sind am schlimmsten betroffen. Sie müssen ausgemerzt werden!\n\nVernichtet alle Bäumlinge, die Ihr dort findet, und sammelt die moosartigen Tumore, die auf ihnen wachsen. Bringt mir die Tumore, damit ich sie verbrennen kann.", objectives = "Bringt Rellian Greenspyre in Darnassus 5 moosartige Tumore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[924] = { title = "Die Dämonensaat", description = "Die Dämonensaat ist ein mächtiges Werkzeug der Brennenden Legion. Sie lebt in einer Höhle des Glutnebelgipfels, oberhalb eines dämonischen Altars des Feuers.\n\nIch habe Kraftsteine vorbereitet, die, wenn sie in der Nähe der Saat platziert werden, deren Verbindung zur Legion unterbrechen.\n\nNehmt einen Stein vom Tisch und bringt ihn zum Altar des Feuers oben auf dem Glutnebelgipfel. Reist nach Westen und bei der Weggabelung weiter nach Norden. Der Gipfel liegt zu Eurer Linken. Die sicherste Aufstiegsmöglichkeit zur Spitze bietet sich an der Nordseite.\n\nUnd beeilt Euch - die Energie des Steins nimmt mit der Zeit ab.", objectives = "Nehmt einen fehlerhaften Kraftstein. Bringt ihn zum Altar des Feuers, bevor dessen Wirkung erlischt, und kehrt dann zu Ak'Zeloth zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[925] = { title = "Cairnes Hufabdruck", description = "Ich habe gehört, dass Cairne Bluthuf einer der größten Helden ist, den die Horde je gesehen hat. Wenn ich mal groß bin, möchte ich auch ein Held der Horde werden!\n\nKennt Ihr Cairne, $n? Tut Ihr mir einen Gefallen? Kriege ich ein Autogramm von ihm? Ich weiß gar nicht, wie ich ihn ansprechen soll, und wahrscheinlich ist er sowieso viel zu beschäftigt, um mich zu beachten...aber was ist mit Euch? Ihr seid doch genau wie er ein Abenteurer! Euch gibt er bestimmt ein Autogramm!\n\nBitte, $n. Bitte...", objectives = "Reist nach Donnerfels und versucht für Euren Schützling einen Hufabdruck von Cairne Bluthuf zu ergattern.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[926] = { title = "Fehlerhafter Kraftstein", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[927] = { title = "Das moosumschlungene Herz", description = "Das Herz von Schwarzmoos dem Stinker ist mit einem dunklen, öligen Moos bedeckt. Dass es sich wirklich um ein Herz handelt, kann man eigentlich nur daran erkennen, dass es langsam und rhythmisch schlägt... Ein Herzschlag, der sogar jetzt noch anhält.\n\nVielleicht würde Denalan dieses Herz gern einmal sehen.", objectives = "Bringt Denalan am Al'Amethsee das moosumschlungene Herz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[928] = { title = "Krone der Erde", description = "Ich könnte Euch zwar noch so viel mehr über die Mondbrunnen und Teldrassil erzählen, doch leider muss ich Euch fortschicken. Corithras Moonrage erwartet Euch. Ich habe das Wasser der Phiole, die Ihr mir brachtet, in dieses Gefäß geschüttet, damit Ihr es ihm bringen könnt.\n\nFragt nach Corithras. Ihr findet ihn am Mondbrunnen in Dolanaar. Folgt der Straße südlich von Aldrassil, die aus Shadowglen hinausführt und dann weiter auf dem Kopfsteinpflaster in Richtung Westen.\n\nBleibt unbedingt immer auf der Straße, $n. Es gibt neuerdings ziemlich gefährliche Bestien in den Wäldern.", objectives = "Bringt Corithras Moonrage in Dolanaar das teilweise gefüllte Gefäß.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[929] = { title = "Krone der Erde", description = "Lasst mich Euch zunächst ein bisschen mehr von der Aufgabe erzählen, die Euch erwartet. Die Druiden in Darnassus verbrauchen das Wasser der Mondbrunnen Teldrassils, und deshalb muss ihr Mondbrunnen von Zeit zu Zeit wieder aufgefüllt werden. Ihr könnt mit diesen speziell gefertigten Phiolen Wasser aus den Mondbrunnen schöpfen.\n\nNehmt dieses Gefäß zum Mondbrunnen außerhalb von Starbreeze im Osten mit und füllt es mit Wasser. Kehrt dann zu mir zurück. Wenn Ihr Eure Aufgabe erledigt habt, erzähle ich die Geschichte da weiter, wo Tenaron aufgehört hat ...", objectives = "Füllt die Jadephiole und bringt sie Corithras Moonrage in Dolanaar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[930] = { title = "Die leuchtende Frucht", description = "Unter den Wedeln dieser leuchtenden Pflanze befindet sich eine große, runde Frucht.\n\nDenalan würde diese Frucht bestimmt gern studieren, da seid Ihr Euch sicher.", objectives = "Bringt Denalan am Al'Amethsee die leuchtende Frucht.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[931] = { title = "Der schimmernde Wedel", description = "Die Wedel der Pflanze schimmern im Dämmerlicht des Waldes und verleihen ihr eine wabernde, pulsierende Aura.\n\nIhr glaubt, dass Denalan bestimmt gern ein Exemplar davon hätte.", objectives = "Bringt Denalan am Al'Amethsee einen der schimmernden Wedel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[932] = { title = "Krankhafter Hass", description = "Ich muss Euch warnen, $n, das hier muss absolut unter uns bleiben. Die Satyrn bereiten uns schon genug Ungelegenheiten, aber dieser eine hier scheint sich zu einer echten Bedrohung zu entwickeln.\n\nLord Melenas ist sein Name. Er lebt in der Nähe des Teufelsfelsens in einer Höhle, in der er ein großes Kontingent Grellkrieger um sich versammelt hat. Sein Herz ist so schwarz wie die Nacht und er führt etwas äußerst Übles im Schilde.\n\nIhr müsst ihn in der nahe gelegenen Höhle gleich nördlich von hier suchen und mir seinen Kopf bringen.", objectives = "Tötet Lord Melenas und bringt Tallonkai Swiftroot in Dolanaar seinen Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[933] = { title = "Krone der Erde", description = "Südöstlich des Ortseinganges von Darnassus, an den Ufern der Teiche von Arlithrien, gibt es noch einen Mondbrunnen. Die Schildwachen können aufgrund von Angriffen und der ständig schlimmer werdenden Hinterhältigkeit der Knarzklauenfurbolgs kaum durch dieses Gebiet patrouillieren.\n\nSeid auf der Hut, wenn Ihr Euch dem Brunnen nähert, und haltet Eure Waffen stets griffbereit.", objectives = "Füllt die Turmalinphiole und bringt sie Corithras Moonrage in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[934] = { title = "Krone der Erde", description = "Mit Teldrassil stand es jedoch nicht zum Besten. Hirschhaupts sorgfältig durchdachte Pläne für den neuen Weltenbaum entwickelten sich nicht so, wie er gehofft hatte, denn es gab ein kleines Problem. Ein Problem, das die Ursache für viele weitere Probleme Teldrassils ist.\n\nWie dem auch sei, dazu komme ich später. Ihr müsst den letzten Mondbrunnen nordwestlich von hier in der Lichtung des Orakels aufsuchen. Unter den Ästen des Orakelbaums befindet sich der wichtigste und mächtigste unserer Brunnen. Beschafft eine Phiole seines Wassers und bringt sie mir.", objectives = "Füllt die Amethystphiole und bringt sie Corithras Mondzorn in Dolanaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[935] = { title = "Krone der Erde", description = "Ohne den Segen Alexstraszas der Lebensbinderin und Nozdormus des Zeitlosen gab es Makel in Teldrassils Wachstum. Man berichtet von seltsamen Wildtieren, die sich buchstäblich aus dem Nährboden des Baums erhoben haben, und von wahnsinnigen Furbolgs, die durchziehende Reisende angreifen.\n\nIch kann nur hoffen, dass der Erzdruide schnellstens eine Lösung für das Problem findet. Ich werde alles Wasser der Phiolen, die Ihr mir brachtet, in dieses Gefäß schütten, damit Ihr es nach Darnassus bringen könnt.\n\nBringt es Fandral Staghelm, Ihr findet ihn im Druidenhain.", objectives = "Bringt dem Erzdruiden Fandral Staghelm in Darnassus das gefüllte Gefäß.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[936] = { title = "Erzdruide Runetotem helfen", description = "Entschuldigung, $C, könnt Ihr einen Moment Eurer Zeit für mich erübrigen?\n\nDer Zirkel des Cenarius in Thunder Bluff ist sehr an erfahrenen Abenteurern wie Euch interessiert, die bei einem wichtigen Forschungsprojekt helfen können. Ich weiß zwar nichts Genaues, kann Euch aber sagen, dass kein Geringerer als Hamuul Runetotem an der Spitze dieses Projektes steht.\n\nBitte... wenn Ihr interessiert seid, sprecht direkt mit ihm auf der Anhöhe der Ältesten in Thunder Bluff.", objectives = "Sprecht in Thunder Bluff mit Erzdruide Hamuul Runetotem.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[937] = { title = "Die verzauberte Lichtung", description = "Man hat mich mit einer kleinen Gruppe Schildwachen hierher beordert, um den Orakelbaum vor den Harpyien zu beschützen, die überall im Tal Nester gebaut haben. Wir versuchen, sie langsam aber sicher zurückzudrängen.\n\nBeim Versuch des Orakelbaums, einen Läufer mit einem Bericht nach Darnassus zu entsenden, wurde dieser von einer Gruppe eben jener Harpyien angegriffen und getötet.\n\nWenn Ihr glaubt, dieser Aufgabe gewachsen zu sein, begebt Euch zu ihren Nestern, erschlagt sie und bringt mir zum Beweis Eurer Taten deren Gürtel.", objectives = "Beschafft 6 Blutfedergürtel und bringt sie der Schildwache Arynia Cloudsbreak in der Lichtung des Orakels.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[938] = { title = "Nebel", description = "Das Fell der Säblerkatze ist von einer auffälligen grauen Farbe, die sich nur wenig vom sie umgebenden Wald abhebt. Wie sie da liegt, erkennt Ihr, dass sie schwer verletzt ist und tiefe Wunden an Rücken und Bauchseite aufweist.\n\nSie hebt ihren Kopf und starrt Euch an, ihre glänzenden blauen Augen voll wacher Intelligenz. Sie scheint Euch folgen zu wollen.", objectives = "Begleitet Nebel zur Schildwache Arynia Cloudsbreak beim Mondbrunnen in der Nähe des Orakelbaums.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[939] = { title = "Flöte des Xavaric", description = "Ihr untersucht die einfache Holzflöte, die Ihr nach dem Sieg über Xavaric aufgehoben habt.\n\nDas knorrige Holz fühlt sich fest an, aber es scheint, als würden sich die Spiralen und Muster auf der Oberfläche bewegen und herumwirbeln, als Ihr sie in den Händen dreht. Plötzlich überkommt Euch ein Gefühl der Furcht...\n\nIhr schüttelt den Kopf, sicher, dass Euch Euer Gehirn einen Streich spielt.\n\nMöglicherweise tragen andere Satyrn Hinweise darüber mit sich, was Ihr da gefunden habt. Bringt Euren Fund zu dem Druiden Eridan Bluewind, der im südlichen Teil des Teufelswalds lebt.", objectives = "Bringt die Flöte von Xavaric und 5 Jadefeuerteufelsbinder zu Eridan Bluewind im südlichen Teil des Teufelswalds.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[940] = { title = "Teldrassil", description = "Der Wald flüstert von Euren wagemutigen Heldentaten, $n. Sobald die Harpyien aus ihren Nestern vertrieben waren, spürte ich, wie sich große Ruhe im Wald verbreitete, und dass sich die Kreaturen des Waldes wieder sicher fühlten. Ich habe nicht gewagt, noch einen Boten zum Erzdruiden zu schicken, aber ich weiß, dass Ihr dafür sorgen werdet, dass ihn meine Nachricht sicher erreicht.\n\nBringt ihm dies und wisset, dass der Wald Euch auf all seinen Wegen beschützen wird, sodass Ihr den Wald aus Stein sicher erreicht.", objectives = "Überbringt dem Erzdruiden Fandral Staghelm in Darnassus den Bericht des Orakelbaums.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[941] = { title = "Das Einpflanzen des Herzens", description = "Ich habe das üble Moos von dem Herzen entfernt, aber es bleibt dennoch besudelt...\n\nVersucht, das Herz in meinem Blumentopf einzusetzen. Er ist mit einer nährstoffreichen Krume gefüllt, die das Herz säubern und heilen kann.", objectives = "Pflanzt das besudelte Herz in Denalans Blumentopf ein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[942] = { title = "Der geistesabwesende Ausgrabungsleiter", description = "Dieses Fossil hat eine auffallende Ähnlichkeit mit einem anderen, das ich einst in Ironforge sah. Ein Archäologe namens Flagongut brachte es zur jährlichen Forscherliga-Konferenz mit. Er dachte, das Fossil besäße eine besondere Macht, die man irgendwie freisetzen könnte.\n\nDas Letzte, was ich von Flagongut hörte war, dass er sich in der Deepwater-Taverne im Hafen von Menethil verschanzt hatte und dort auf eine Eskorte zu Whelgars Ausgrabungsstätte wartete. Sucht ihn auf und zeigt ihm Remtravels Fossil. Vielleicht kann er die Geheimnisse der Vergangenheit lüften.\n\nDas Schiff nach Menethil liegt in Auberdine.", objectives = "Bringt das rätselhafte Fossil zum Archäologen Flagongut im Hafen von Menethil.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[943] = { title = "Der geistesabwesende Ausgrabungsleiter", description = "Ausgrabungsleiter Whelgar ist jetzt im Besitz des Originalfundstücks. Er hält sich in seiner Ausgrabungsstätte im Sumpfland auf. Als ich den Stein von Relu entdeckte, glaubte ich, dass er der Schlüssel sei, mit dem das Rätsel des Fossils gelöst werden könne.\n\nAuf dem Weg zu Whelgar wurde ich dann von Raptoren angegriffen und das Relikt ging verloren. Ich weiß nicht, welche dieser scheckigen Bestien das Relikt verschlungen hat, aber falls es Euch gelingen sollte, es zurückzuholen, könnte ich die Macht dieser Artefakte freisetzen.\n\nBringt mir den Stein von Relu und das Originalfossil.", objectives = "Der Archäologe Flagongut im Hafen von Menethil möchte, dass Ihr ihm den Stein von Relu und Flagonguts Fossil bringt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[944] = { title = "Die Meistergleve", description = "Wie seltsam, dass sich Naga hier herumtreiben, hier in Dunkelküste. Aber was noch seltsamer ist... es sind auch welche vom Klan der Twilight-Hammer da. Dieser Kult verehrt die alten, alten Lords der Erde. Lords, die schon vor Unzeiten besiegt wurden.\n\nDie Meistergleve im Süden ist ein Ort, an dem ein solcher Lord einst gefallen ist.\n\nBegebt Euch dorthin und sucht nach weiteren Anhängern der Twilight-Hammer-Kultisten.\n\nNehmt diese Wahrsagephiole. Erschafft damit eine Wahrsageschale, nachdem Ihr die Meistergleve durchsucht habt. Sprecht dann mit mir mittels der Schale.", objectives = "Tragt Informationen zusammen und benutzt dann die Wahrsagephiole, um eine Wahrsageschale zu erschaffen. Benutzt die Schale, um mit Onu zu sprechen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[945] = { title = "Therylunes Flucht", description = "Hilfe!\n\nDiese dreckigen Kultisten haben mich umzingelt, während ich durch die Meistergleve spazierte. Was für ein Glück, dass ich so gut im Verstecken bin!\n\nKönnt Ihr mir hier raushelfen? Ich sollte auch meiner Schwester Therysil Bescheid geben, dass es mir gut geht. Sie wohnt in Ashenvale im Süden, beim Schrein von Aessina.", objectives = "Verhelft Therylune zur Flucht und teilt dann Therysil beim Schrein von Aessina mit, dass ihre Schwester in Sicherheit ist.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[947] = { title = "Höhlenpilze", description = "Ich entwickle gerade einen Trank, für den rare Pilze erforderlich sind. Pilze, die nur in einer bestimmten Höhle wachsen. Diese Höhle liegt hinter Cliffspring Falls im Osten, leicht nördlich entlang der Berge.\n\nIch würde ja selbst dorthin gehen, aber der Hain der Uralten hat mir geraten, mich von diesem Ort fern zu halten. Unsere altehrwürdigen Verbündeten spüren, dass die Höhle ein Versteck für etwas Neues, Böses in Dunkelküste ist.\n\nBitte, $N, sammelt doch ein paar Pilze für mich, und wenn Ihr schon dabei seid, könntet Ihr auch gleich die Höhle erkunden, um die Befürchtungen der Urtume eventuell zu bestätigen.", objectives = "Bringt Barithras Moonshade in Auberdine 5 Schorfstänglinge und 1 Todeskappe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[948] = { title = "Onu", description = "Onu, ein Urtum der Lehren im Hain der Uralten, hat von Eurer Reise nach Cliffwaterfalls erfahren und möchte Euch sprechen. Der Hain liegt im Süden, im Schatten der Berge.\n\nDie Urtume sind geduldig und weise, $N. Aber wenn Onu Euch um Rat bezüglich dessen ersucht, was Ihr in den Falls gesehen habt, fürchte ich, dass es wichtig ist.", objectives = "Sprecht im Hain der Uralten mit Onu.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[949] = { title = "Das Twilight-Lager", description = "Niemand weiß, was der Klan der Twilight-Hammer in der Meistergleve vorhat. Aber es muss etwas Böses sein.\n\nDurchsucht ihr Lager bei der Meistergleve... Sucht nach etwas, das uns ihre Absichten verraten könnte.\n\nWir müssen unbedingt wissen, was sie im Schilde führen, bevor wir einen Plan schmieden können.", objectives = "Sucht im Lager des Klans der Twilight-Hammer in der Meistergleve nach einem Hinweis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[950] = { title = "Rückkehr zu Onu", description = "Der Blick in den Twilight-Folianten kann einen wahnsinnig machen. Der Text verschwimmt und tanzt vor Euren Augen, kaum dass Ihr ihn einen Moment betrachtet habt, und die einst so wunderschönen Illustrationen verzerren sich zu grotesken Formen und Mustern.\n\nIhr könnt gerade noch eine Seite des irrsinnigen Gekritzels herausreißen, bevor Ihr ohnmächtig werdet.", objectives = "Bringt Onu das irrsinnige Gekritzel, das Ihr gefunden habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[951] = { title = "Mathystra-Relikte", description = "Das Pergament, das Ihr in der Meistergleve gefunden habt, ist eine Seite aus einem alten Text... geschrieben von Elfen! Es ist übelst verflucht und besudelt von der Verderbnis des Klans der Twilight-Hammer, aber es scheint, als würde der Kult alte Elfenmagie benutzen, um seine alten Lords in unsere Welt zurückzuholen.\n\nReist zu den Ruinen von Mathystra im Nordosten und sucht nach alten Relikten unter dem Gras und den zerbrochenen Steinen. Indem wir sie studieren, können wir vielleicht herausbekommen, auf welche Weise der Klan der Twilight-Hammer die Magie der Elfen nutzen will.", objectives = "Bringt 6 Mathystra-Relikte zu Onu in den Hain der Uralten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[952] = { title = "Der Hain der Uralten", description = "Wenn Ihr genug Zeit hattet, um für den Orakelbaum Nachrichten zu übermitteln, kann ich Euch sicherlich dazu bewegen, eine Nachricht in den Hain der Uralten in Dunkelküste zu bringen, südlich von Auberdine.\n\nIhr werdet höchstwahrscheinlich ein sicheres Transportmittel wie einen Hippogryphen benötigen, aber ich baue darauf, dass Ihr das regeln könnt. Bringt dies Onu, dem Urtum der Lehren. Er wartet auf eine Nachricht von mir, so wie ich auf Neuigkeiten aus der Lichtung des Orakels wartete.", objectives = "Bringt Fandrals Nachricht zu Onu in den Hain der Uralten in Dunkelküste, südlich von Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[953] = { title = "Der Untergang von Ameth'Aran", description = "Im Osten findet Ihr die Ruinen von Ameth'Aran. Sie werden heute von den ruhelosen Geistern der Hochgeborenen bewohnt, die einst dort lebten. Damals jedoch war es ein Ort, an dem die Diener Azsharas ihre mächtige Magie ungestört praktizieren konnten.\n\nMan hat mich geschickt, die Ruinen zu erkunden und ich stieß auf zwei große Schrifttafeln, auf denen die Geschichten Ameth'Arans und seines Unterganges beschrieben werden. Während ich die Runen las, traten Geister an mich heran und ich floh.\n\nBitte, wenn es Euch möglich ist, begebt Euch zu den Ruinen und entziffert an meiner statt die Schrifttafeln.", objectives = "Studiert die Schrifttafeln, die von Ameth'Aran und ihrem Untergang erzählen, und kehrt dann zur Schildwache Tysha Moonblade in Dunkelküste zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[954] = { title = "Bashal'Aran", description = "Die Ruinen von Bashal'Aran im Osten sind von dämonischen Dienern überrannt worden. Die Grimmlinge und Satyrn haben sich in dem Gebiet niedergelassen und nähren sich von den magischen Energien dort. Ihre Macht wächst, je länger sie sich dort aufhalten.\n\nDennoch habe ich festgestellt, dass es dort einen Schrein gibt, dem sie nicht zu nahe kommen wollen. An der Westseite der Ruinen auf einem kleinen Steilhang entspringt eine seltsame blaue Aura ... Das muss eine Erklärung für das Widerstreben der Dämonen sein.\n\nIch hätte gern, dass Ihr das untersucht.", objectives = "Sucht in den Ruinen von Bashal'Aran nach der Quelle der seltsamen blauen Aura.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[955] = { title = "Bashal'Aran", description = "Sollte ich jemals gehalten sein, die Geschichte meines Lebens zu erzählen, würde dies zweifellos die Grenzen Eurer Geduld überstrapazieren. Sagen wir einfach, dass mein Leben lang und schmerzvoll war, und dass diese meine spektrale Gestalt die schlimmste Pein von allem ist.\n\nIch werde durch Magie hier festgehalten. Mögen meine Worte auch unaufrichtig erscheinen, so versichere ich Euch doch, dass ich über die Maßen dankbar wäre, würdet Ihr mir helfen, den Grund für meine Gefangenschaft herauszufinden. Ein Siegel bindet mich, und vielleicht finde ich einen Hinweis darauf, wenn ich den Ohrschmuck der Grimmlinge und Grells nur näher betrachten könnte.", objectives = "Beschafft für Asterion in Bashal'Aran 8 Grell-Ohrringe.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[956] = { title = "Bashal'Aran", description = "Wenn die Grells erst kürzlich mit dem Siegel in Berührung gekommen sind, das mich an dieses ewige Gefängnis bindet, glaube ich, den Grund dafür zu wissen. Zweifellos ist das Siegel in den Besitz des Satyrs gelangt, der sie anführt.\n\nIch bin mir ganz sicher, dass es so ist, $n. Einer der Satyrn muss es besitzen. Wenn Ihr es an Euch bringen könntet, würde es mich der Überwindung der Gitterstäbe meines Gefängnisses so nahe bringen, dass es mich zu Tränen rühren würde.", objectives = "Beschafft das alte Mondstein-Siegel und bringt es Asterion in Bashal'Aran.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[957] = { title = "Bashal'Aran", description = "Es war die Kunst eines der mächtigsten Hochgeborenen, der das Siegel erschuf, das mein Gefängnis war. In Ameth'Aran, den Ruinen im Süden, die diesen hier aufs Haar gleichen, gibt es sogar heute noch eine uralte Flamme, blau ist ihre Farbe. In dieser Flamme könnte man dieses Siegel zerstören.\n\nAchtet auf die Ruinen, $n!", objectives = "Zerstört das alte Mondstein-Siegel in der uralten Flamme in Ameth'Aran und kehrt dann zu Asterion in Bashal'Aran zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[958] = { title = "Werkzeuge der Hochgeborenen", description = "$C. Ich möchte Euch um etwas bitten.\n\nHabt Ihr die Ruinen von Ameth'Aran gesehen? Falls nicht, findet Ihr sie auf der Ostseite der Hauptstraße, ein paar Straßen weiter südlich. Einst waren sie die Heimat vieler mächtiger Hochgeborener, doch heute sind sie Zeugnis der Zerstörung, die sie mit ihrem Dilettantismus angerichtet haben.\n\nDie Schildwachen sagten mir, dass die Geister der Hochgeborenen immer noch umgehen und dass sie ihre alten, magischen Utensilien immer noch benutzen. Wir müssen uns diese Relikte aneignen, damit wir sie zerstören können.", objectives = "Sucht sieben Hochgeborenenrelikte und bringt sie Thundris Windwirker in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[959] = { title = "Ärger auf den Docks", description = "Upps!\n\nWie Ihr seht, ist mir ein kleines Malheur passiert! Die Morgenlieferung aus Booty Bay war umfangreich. Wirklich gewaltig! Noch nie habe ich so viele Kisten gesehen. Tja, ich wollte die Sache etwas beschleunigen, deshalb habe ich begonnen mehr abzuladen, als ich auf einmal bewältigen konnte. Und dann ist alles zusammengebrochen.\n\nBevor ich wusste, was überhaupt los war, sah ich diese Nervensäge Zausel den Verrückten mit einer Flasche 99-jährigem Portwein wegrennen. Hab ihn bis zu den Höhlen des Wehklagens verfolgt. Da wollte ich auf keinen Fall rein.\n\nVielleicht seid Ihr ja mutig genug, um nach ihm zu suchen?", objectives = "Kranführer Bigglefuzz in Ratchet möchte, dass Ihr Zausel dem Verrückten, der sich in den Höhlen des Wehklagens versteckt, die Flasche mit 99-jährigem Portwein wieder abnehmt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[961] = { title = "Onu meditiert", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[962] = { title = "Schlangenflaum", description = "Die Königliche Apothekervereinigung, die in der großen Undercity Lordaerons ansässig ist, hat mich geschickt, um eine ganz besondere Aufgabe zu erledigen, $n. Vielleicht möchtet Ihr mich und damit auch die dunkle Fürstin bei unseren Bemühungen, die Verlassenen weiterzubringen, unterstützen.\n\nIch studiere seit kurzem eine rare Pflanzenart namens Schlangenflaum. Ich denke, dass dieses Kraut in größeren Mengen außerordentliches Potenzial besitzt.\n\nLeider findet man Schlangenflaum nur in den dunkelsten Winkeln der Höhlen des Wehklagens, einem gefährlichen Höhlensystem im Brachland.", objectives = "Die Apothekerin Zamah in Thunder Bluff möchte, dass Ihr zehn Schlangenflaum für sie sammelt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[963] = { title = "In ewiger Liebe", description = "Nach den Schlachten um den Brunnen der Ewigkeit hörte ich, dass Ameth'Aran zerstört wurde und alle Bewohner ums Leben kamen, darunter auch meine geliebte Anaya.\n\nIch hätte nie gedacht, dass mich noch heute, Tausende von Jahren später, die Erinnerungen an Anaya um den Schlaf bringen würden. Ich wanderte wie in Trance durch die Wälder von Dunkelküste und fand mich schließlich in den Ruinen von Ameth'Aran wieder... wo ich den gequälten Geist meiner Geliebten sah.\n\nSie muss befreit werden, aber ich kann es nicht über mich bringen, dies zu tun. Ihr Geist muss zerstört werden.", objectives = "Befreit den Geist von Anaya Dawnrunner und bringt ihren Anhänger zu Cerellean Whiteclaw in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[964] = { title = "Skelettfragmente", description = "Der Schlüssel zur Scholomance wird 'Skelettschlüssel' genannt. Er muss aus den Überresten eines Skeletts geschmiedet werden- eigentlich aus mehreren - und er darf nur durch die stärksten Metalle in einer geeigneten Form gehärtet werden. Ein Signet der Macht von einem Wesen, das das Portal zur Scholomance natürlich öffnen kann, gibt dem Schlüssel seine endgültige Funktion.\n\nAber eines nach dem anderen, $N. Wir benötigen Skelettfragmente für das Schmieden des Schlüssels. Skelette innerhalb von Andorhal sollten den gewünschten Effekt bringen, aber die außerhalb der Mauern könnten vielleicht auch ausreichen.", objectives = "Bringt 15 Skelettfragmente zu Apotheker Dithers am Bollwerk, Westliche Pestländer.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[965] = { title = "Der Turm von Althalaxx", description = "Grüße, $R. Ich bin Elissa Starbreeze und es ist meine Aufgabe, Auberdine vor Schaden zu schützen.\n\nAus diesem Grund habe ich Balthule Shadowstrike ausgeschickt, um die seltsamen Vorkommnisse rund um den Turm von Althalaxx im Nordosten zu beobachten.\n\nEr hätte eigentlich schon längst wieder zurück sein sollen. Daher fürchte ich, dass er im Wald auf eine unvorhersehbare Gefahr gestoßen ist. Ich würde es außerordentlich zu schätzen wissen, wenn Ihr nach ihm suchen und dafür sorgen würdet, dass es ihm gut geht.", objectives = "Sucht Balthule Shadowstrike in der Nähe des Turms von Althalaxx in Dunkelküste.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[966] = { title = "Der Turm von Althalaxx", description = "Eine Gruppe Hexenmeister hat sich in und um den Turm herum niedergelassen. Ich wollte ja schon früher nach Auberdine zurückkehren, um Elissa Bericht zu erstatten, aber ich befürchtete, hier etwas zu verpassen, solange ich fort wäre.\n\nDelgren vermutete, dass sich eine solche Gesellschaft beim Turm versammeln würde, aber er wusste nicht, warum.\n\nEin paar Pergamentfetzen, die die Hexenmeister bei sich führten, sind mir in die Hände gefallen, aber ich brauche noch mehr, um das Rätsel zu lösen. Ich warne Euch jedoch, geht lieber nicht in den Turm hinein, denn die Hexenmeister dort sind noch viel mächtiger!", objectives = "Sammelt 4 abgenutzte Pergamentfetzen für Balthule Shadowstrike in der Nähe des Turms von Althalaxx.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[967] = { title = "Der Turm von Althalaxx", description = "Mein Meister, Delgren der Läuterer, ist ein Paladin, der gütigerweise seine Unterstützung bei der Verteidigung unseres Waldes vor den Streitkräften der Dämonen und Untoten angeboten hat. Er hat mich viel über das Heilige Licht und die Kampfkunst gelehrt.\n\nDelgren muss sofort über die Machenschaften des Kults informiert werden.\n\nIhr findet ihn ganz weit südlich von hier in Maestras Posten in Ashenvale. Beeilt Euch, ich fürchte nämlich, dass die Bedrohung durch den dunklen Strangs stündlich größer wird.", objectives = "Überbringt Delgren dem Läuterer in Ashenvale Balthules Brief.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[968] = { title = "Die Macht in der Tiefe", description = "Obwohl das Buch ziemlich abgenutzt und zerfleddert ist, ist der Titel auf dem Buchdeckel noch gut lesbar:\n\n'Die Macht in der Tiefe'\n\nIn diesem Buch findet sich eine Auflistung unaussprechlicher Namen mit viel sagenden Betitelungen, Verehrungsmethoden und bevorzugten Opferritualen ... bei denen sehr oft lebende, humanoide Kreaturen verwendet werden.\n\nAuf der Innenseite des Einbands stehen die Worte: 'Bonegrips Runen und Verhängnisse, Düsteres Viertel, Ironforge. Inhaber: Gerrig Bonegrip.'\n\nWenn Bonegrip derartige Bücher verkauft, nimmt er dieses hier vielleicht zurück.", objectives = "Bringt das Buch: 'Die Macht in der Tiefe' zu Gerrig Bonegrip im düsteren Viertel in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[969] = { title = "Das Glück sei mit Euch", description = "Ah, ich seh's Euch direkt an: Ihr möchtet, dass ich Euch einen Glücksbringer anfertige. Mau'ari weiß immer Bescheid!\n\nIm Süden, findet Ihr eine Schlucht und Riesen, die komplett aus Eis bestehen. Die Riesen tragen die Splitter manchmal bei sich, aber Ihr könnt sie auch selbst in der Schlucht sammeln. Diese Splitter haben mächtige reflektierende Eigenschaften.\n\nBringt mir 10 Frosthagelsplitter und mein Glücksbringer wird Euch gehören.", objectives = "Sammelt 10 Frosthagelsplitter für die Hexendoktorin Mau'ari in Everlook.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[970] = { title = "Der Turm von Althalaxx", description = "Balthules Brief verkündet Unheil. Dieser Kult des Dunklen Strangs ist mir ein Dorn im Auge, der entfernt werden muss. Ich hatte nordöstlich von hier in Ordil'Aran schon einmal mit dem Abschaum des Dunklen Strangs zu tun. Eines seiner Mitglieder besitzt einen Seelenedelstein, der, wie ich glaube, das Geheimnis der Macht des Kults enthält.\n\nBringt ihn mir, dann kann ich die darin zu findenden Geheimnisse entschlüsseln.", objectives = "Beschafft einen leuchtenden Seelenedelstein und bringt ihn Delgren dem Läuterer in Maestras Posten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[971] = { title = "Wissen in der Tiefe", description = "Wie Ihr vielleicht wisst, trage ich Lehren zusammen. Alte Lehren. Mächtige Lehren. Lehren, die Portale öffnen, und Lehren, die die Schlafenden erwecken können.\n\nEs kursieren Gerüchte um einen alten Teil einer Lehre, das 'Lorgalis-Manuskript', das sich tief unten in den Blackfathom-Tiefen in Ashenvale befinden soll. Dieser Ort ist die ehemalige Heimat längst verstorbener Elfen. Elfen, die über großes Wissen verfügten, bevor ihre Stadt zerfiel.\n\nSucht in den Blackfathom-Tiefen nach dem Manuskript. Wenn Ihr das tut, werde ich Euch das nie vergessen. Auch nicht ... nach dem Ende aller Tage.", objectives = "Bringt das 'Lorgalis-Manuskript' zu Gerrig Bonegrip in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[972] = { title = "Wassersapta", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[973] = { title = "Der Turm von Althalaxx", description = "Ilkrud Magthrull. Ja, ich kenne ihn. Er ist ein mächtiger Orc-Hexenmeister, der im Fire Scar-Schrein lebt, einem äußerst bösen Ort im südwestlichen Ashenvale.\n\nBislang ist er nur ein geringes Ärgernis und ich hatte noch nichts mit ihm zu tun, aber es sieht so aus, als wäre jetzt seine Zeit gekommen.", objectives = "Bringt Delgren dem Läuterer in Maestras Posten Ilkrud Magthrulls Folianten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[974] = { title = "Die Quelle finden", description = "Die heißen Quellen hier sind eine Quelle der Geheimnisse für mich. Woher kommt die Hitze?\n\nWenn ich mir überlege, wie nah diese Teiche beim Feuerfedergrat sind, frage ich mich wirklich, ob der Vulkan etwas damit zu tun hat. Ich habe ein Thermometer entwickelt, um die Temperaturen am Vulkan zu messen, und ich würde gern die heißeste Stelle finden. Es zeigt die Messungen in Grad Kraklenheit an!\n\nHier, nehmt es und messt die Temperaturen am Grat, wann immer Ihr eine heiße Stelle seht!", objectives = "Krakle im Un'Goro Krater möchte, dass Ihr den heißesten Bereich des Feuerfedergrats findet.\n\nImmer, wenn Ihr eine heiße Stelle findet, klickt Ihr das Thermometer mit der rechten Maustaste an, um die Temperatur zu überprüfen. Sucht, bis Ihr die heißeste Stelle gefunden habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[975] = { title = "Behälter von Mau'ari", description = "Also, bevor ich Euch dies'n Glücksbringer geb, erklär ich Euch besser, wie er zu verwenden is'.\n\nWenn Ihr den Glücksbringer bei Euch tragt, werdet Ihr feststell'n, dass die Kreaturen, gegen die Ihr kämpft, bestimmte Gegenstände fallen lassen. Wenn Ihr den Glücksbringer nich' dabei habt, werdet Ihr sie nich' find'n. Kapiert?\n\nIhr erkennt diese speziellen Gegenstände am Namen - sie werden E'ko genannt. Wenn Ihr solche Gegenstände findet, bringt Ihr sie einfach der alten Mau'ari, und sie hilft Euch.\n\nWartet hier, während ich Euren Glücksbringer anfertige.", objectives = "Wartet einen Moment und sprecht dann erneut mit Hexendoktorin Mau'ari, um den Glücksbringer zu erhalten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[976] = { title = "Nachschub für Auberdine", description = "Delgren hat mich gebeten, der Schildwache Starbreeze in Auberdine Nachrichten und Nachschub zu bringen, aber es schmeckt mir gar nicht, allein dorthin zu gehen. Im Wald sind gefährliche Feinde zugange und ich möchte nicht riskieren, dass der Nachschub und die Informationen in die falschen Hände geraten.\n\nWenn Ihr und ein paar andere als Wachen mit mir kämen, könnte ich sofort gehen. Mit Eurem Schutz zweifle ich nicht daran, dass wir diese Dinge sicher nach Auberdine bringen können.", objectives = "Sprecht mit Delgren dem Läuterer bei Maestras Posten, nachdem Ihr Feero sicher durch Ashenvale geführt habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[977] = { title = "Sind wir endlich da, Yeti?", description = "Nachdem ich jetzt alles habe, was ich benötige, um die mechanischen beweglichen Teile abzudecken, benötige ich nur noch eine weitere Sache. Na ja, eigentlich zwei. Zwei Hörner!\n\nDie Eisdistelpatriarchen und -matriarchen haben die größten Hörner, also will ich natürlich diese. Diese Yetiart bewohnt eine Höhle im Südosten. Es gibt viele von ihnen; Ihr solltet keine Probleme haben, sie zu finden.\n\nDenkt daran, ich will nur die bestaussehenden - keine beschädigten oder zerbrochenen Hörner, bitte!", objectives = "Sammelt 2 makellose Yetihörner für Umi Rumplesnicker in Everlook.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[978] = { title = "Mondbestrahltes Wildekin", description = "Wildekinfedern aus dem Hinterland scheinen Spuren magischer Fähigkeiten zu enthalten. Diese Kräfte... sie scheinen von den Kreaturen nicht bewusst eingesetzt zu werden, es scheint eher, als wären sie der Art angeboren; ein Teil ihres innersten Wesens.\n\nWährend meiner Studien habe ich gehört, dass eine große Population von Wildekins die schneebedeckten Länder von Winterspring bewohnt. Könnten diese Kreaturen über die gleichen Kräfte verfügen? Helft mir bitte, eine Antwort zu finden, $N. Begebt Euch nach Winterspring und sammelt die auf dem Boden gefallenen Federn ein. Kehrt dann zu mir zurück.", objectives = "Sammelt 10 mondbestrahlte Federn aus Winterspring und kehrt dann zu Erelas Ambersky in Rut'theran zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[979] = { title = "Ranshalla suchen", description = "Ja, ja, diese Federn scheinen die gleiche magische Verzauberung zu enthalten, die mir schon zuvor auffiel... Auch wenn ich mir nicht sicher bin, was wir vorfinden werden, solltet Ihr weiterhin nach Antworten suchen, $N.\n\nEine meiner Kolleginnen reiste kürzlich nach Winterspring, um die Wildekin dort in ihrer heimischen Umgebung zu beobachten. Warum sucht Ihr sie nicht auf und seht, was sie herausgefunden hat?", objectives = "Sucht nach Ranshalla im östlichen Winterspring.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[980] = { title = "Die neuen Quellen", description = "Tja, ich habe von anderen heißen Quellen an einem Ort namens Winterspring gehört, von hier aus gesehen weit im Norden. Das Merkwürdige ist, dass es dort in der Nähe keine Vulkane gibt. Interessant, ich weiß.\n\nAlso, wenn Ihr mehr herausfinden möchtet, solltet Ihr Euch nach Winterspring begeben und mit einer Freundin von mir sprechen. Ihr Name ist Donova Snowden und sie hält sich derzeit bei den heißen Quellen dort auf.\n\nIch danke Euch erneut, dass Ihr mir mit meinem Thermometer geholfen habt! Auf dann!", objectives = "Reist nach Winterspring und sprecht mit Donova Snowden.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[981] = { title = "Der Turm von Althalaxx", description = "Für all das, was Ihr geleistet habt, habt Ihr eine ordentliche Belohnung verdient. Kehrt zu Delgren zurück und sagt ihm, dass Ihr Athrikus Narassin eigenhändig den Garaus gemacht habt, und dass der Kult des Dunklen Strangs zerschlagen ist.", objectives = "Sprecht mit Delgren dem Läuterer in Maestras Posten.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[982] = { title = "Tiefer Ozean, weites Meer", description = "Nahe der Ufer von Dunkelküste im Norden liegen zwei havarierte Schiffe - die SILBERMORGEN und die NEBELSCHLEIER. Vor einiger Zeit kollidierten die beiden Schiffe wegen der verfluchten Murlocs, als sie über das weite Meer nach Auberdine segelten. Jetzt liegen sie auf dem Grund des Ozeans als Trophäen für diese Satanskreaturen.\n\nBeide Kapitäne haben es in dieser Nacht nicht geschafft, ihre Schiffe zu verlassen. Ihre Logbücher und anderen Habseligkeiten befinden sich immer noch dort unten in Schließkassetten. Ich möchte Euch bitten, sie für uns zu beschaffen; es würde den Mannschaftsmitgliedern, die sich noch hier aufhalten, viel bedeuten.", objectives = "Beschafft die Schließkassette der SILBERMORGEN und die Schließkassette der NEBELSCHLEIER für Gorbold Steelhand in Auberdine. Beide Gegenstände findet Ihr an Bord der Schiffswracks nördlich des Dorfes.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[983] = { title = "Dröhnkiste 827", description = "He! Helft mir bei meiner neuesten Erfindung, der Dröhnkiste. Man kann damit mit Leuten sprechen, die weit weg sind!\n\nVielleicht habt Ihr sie schon mal gesehen, das sind kleine Kästchen mit Hebeln daran. Ihr einziges Problem ist, dass sie ständig gewartet werden müssen.\n\nJede hat ein anderes Problem, aber ich hab mir etwas ziemlich Schlaues ausgedacht. Ich habe alle in der Nähe von Kreaturen platziert, die über die passenden Teile verfügen, um die jeweilige Maschine zu reparieren. Momentan hat Dröhnkiste 827 den Geist aufgegeben. Sie steht südlich von Auberdine, also gleich in der Nähe. Es werden sechs Kriecherbeine benötigt, um sie zu reparieren. Ich bezahl Euch auch dafür ...", objectives = "Sammelt 6 Kriecherbeine und baut sie in Dröhnkiste 827 ein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[984] = { title = "Wie groß ist die Bedrohung?", description = "Einige meiner Brüder konnten in Teldrassil vor einem verderbten Furbolg gerettet werden und ich habe geschworen, weitere Gräueltaten zu verhindern, bevor noch mehr von uns verletzt werden... oder schlimmer.\n\nIch habe auch in Dunkelküste schon die ersten Anzeichen von Verderbnis entdeckt, jedoch noch nichts gefunden, was auf Ausbreitung hindeutet. Ich denke, es wäre logisch, wenn man die Untersuchungen bei den Furbolgs fortsetzen würde. Würdet Ihr wohl eines ihrer Lager aufsuchen und zu mir zurückkehren, falls Ihr dort irgendwelche Anzeichen von Verderbnis entdeckt?", objectives = "Sucht in Dunkelküste nach einem verderbten Furbolglager und kehrt dann zu Terenthis in Auberdine zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[985] = { title = "Wie groß ist die Bedrohung?", description = "Ihr habt Euer Talent im Ausspähen unserer Feinde bereits unter Beweis gestellt, $n. Aber habt Ihr auch das Zeug dazu, sie zu bekämpfen?\n\nNicht alle Abenteurer ziehen ein offenes Gefecht der Kunst der Verstohlenheit und des Ausweichens vor.\n\nWenn Ihr glaubt, der Aufgabe gewachsen zu sein, solltet Ihr Euch das Furbolglager südlich von Auberdine vornehmen. Das stellt momentan die größte Bedrohung für unser Volk dar. Ihr werdet dort ein paar Mitglieder des Schwarzfellstamms finden. Tötet 8 Pfadfinder und 5 Windsprecher und kommt dann zu mir zurück.", objectives = "Tötet 8 Pfadfinder der Schwarzfelle und 5 Windsprecher und kehrt dann zu Terenthis in Auberdine zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[986] = { title = "Ein verirrter Meister", description = "$N, Eure Fertigkeiten haben mir bei meinen Bemühungen sehr geholfen. Kann ich es wagen, Euch dennoch erneut zu bitten, Grimmklaue und seinem Meister Volcor zu helfen? Ich könnte Euch dazu einen magischen Umhang anfertigen, mit dem Ihr ungehindert an den Kreaturen Dunkelküstes vorbeigelangt, während Ihr nach ihm sucht.\n\nUm den Umhang anzufertigen, benötige ich fünf Mondpirscherpelze von einer Mondpirschermatriarchin oder einem Mondpirscherpatriarchen, um genügend Material zur Verfügung zu haben. Die Katzen findet Ihr südlich von hier, in der Nähe des Flusses Wildbend, oder noch weiter im Süden, in der Nähe von Ashenvale.", objectives = "Sucht 5 feine Mondpirscherpelze und bringt sie Terenthis in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[990] = { title = "Marsch nach Ashenvale", description = "$N, meine Herrin Raene Wolfrunner erwartet Euch in Astranaar in Ashenvale. Mit Eurer Hilfe könnten wir vielleicht wenigstens eines Teils der Verderbnis Herr werden, die sich dort breit gemacht hat.\n\nGeht von hier aus nach Süden und haltet Euch dicht an der Straße. Wenn Ihr Euch an diese Richtungsangaben haltet, erreicht Ihr problemlos Euer Ziel.", objectives = "Sucht Raene Wolfrunner in Ashenvale auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[991] = { title = "Raenes Säuberung", description = "$N, ein alter Freund von mir unterstützt hier in Ashenvale ebenfalls die Schildwachen, aber er ist noch nicht zurückgekehrt.\n\nEr ging einer Spur nach, die zu einem Gegenstand führte, der seiner Meinung nach die Angriffe der Furbolgs auf unser Volk verlangsamen könnte - eine Rute, die von einem mittlerweile verstorbenen, bösen Hexer geschaffen wurde.\n\nVor seiner Abreise erwähnte er, dass er nach einem Edelstein für die Rute suchen wolle.\n\nEr meinte, dass dieser Edelstein möglicherweise in dem Schrein im Falathimsee am Fuße der Berge im Westen versteckt sei. Dort wurde der Edelstein jedenfalls aufbewahrt, bevor der Schrein überrannt worden ist.\n\nBitte, $N, findet meinen Freund.", objectives = "Sucht in Ashenvale nach Teronis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[992] = { title = "Gadgetzan Wassersondierung", description = "Wenn Ihr interessiert seid, hätten wir einen offenen Posten im Rang eines temporären Unterfeldmessers in der Gadgetzan Water Company.\n\nDa die Nomaden unsere Brunnen erobern, müssen wir weitere freie Wasserquellen ausschöpfen! Es gibt Wasser in der Wüste, aber nur für die, die klug genug sind, sie erst zu erforschen.\n\nNehmt diesen Wünschelrutenapparat und zapft damit eine Wasserprobe vom Teich in der Nähe der Sandsorrow-Wache. Er befindet sich direkt in Sichtweite der Trolle dort. Bringt mir den angezapften Apparat zurück, wenn Ihr fertig seid!", objectives = "Benutzt den unangezapften Wünschelrutenapparat in der Nähe des Teichs bei der Sandsorrow-Wache. Bringt den angezapften Wünschelrutenapparat zum Leitenden Feldmesser Fizzledowser nach Gadgetzan zurück, wenn Ihr die Probe entnommen habt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[993] = { title = "Ein verirrter Meister", description = "Der Umhang ist fertig, $n. Jetzt ist es an der Zeit, Volcor zu suchen. Ich hoffe nur, dass wir es noch rechtzeitig schaffen.\n\nDie Magie des Umhangs hält nicht lang an, nachdem sie herbeigerufen wurde - etwa fünf Minuten. Es liegt an Euch zu entscheiden, wann Ihr sie benutzt: Ich schlage vor, dass Ihr damit wartet, bis Ihr Grimmklaue gefunden habt.\n\nFalls es wahr ist, was er mir erzählte, findet Ihr seinen Meister in einer Höhle südlich von hier. Grimmklaue wird an der Straße auf Euch warten. Gebt ihm ein Signal, indem Ihr winkt, sobald Ihr ihn gesehen habt, dann wird er Euch den Weg zu seinem Meister weisen.", objectives = "Sucht Volcor in Dunkelküste und gebt ihm den verzauberten Mondpirscherumhang.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[994] = { title = "Flucht durch Gewalt", description = "Gut, $n, dann sei es Gewalt. Lasst uns hier verschwinden, sobald Ihr bereit seid. Wir werden uns unseren Weg hinunter zur Straße erkämpfen - Grimmklaue dürfte immer noch dort sein. Sobald wir sie erreicht haben, können wir uns trennen.\n\nTerenthis wird sofort Eure Version der Geschichte hören wollen, also geht nach Auberdine, sobald wir es hier herausgeschafft haben.", objectives = "Beschützt Volcor, bis Ihr die Straße erreicht habt und sprecht dann mit Terenthis in Auberdine.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[995] = { title = "Flucht durch Verstohlenheit", description = "Na gut... wenn Ihr sicher seid, werden wir uns hier hinausschleichen. Lasst uns verschwinden, sobald Ihr bereit seid.\n\nVergesst nicht, Euch in Auberdine mit Terenthis zu treffen, sobald Euch die Flucht gelungen ist. Ich werde mich auf eigene Faust dort hinbegeben, da ich wahrscheinlich schneller bin als Ihr.", objectives = "Flieht aus der Furbolghöhle und trefft Euch in Auberdine mit Terenthis.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[996] = { title = "Verderbte Windblüte", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[997] = { title = "Denalans Erde", description = "Seid Ihr nach Süden unterwegs? Zum Al'Amethsee? Wenn dem so ist, möchte ich Euch um einen Gefallen bitten...\n\nMein Kollege Denalan hat am Ostende des Sees ein Lager aufgeschlagen, in dem er die Pflanzenwelt Teldrassils studiert und Experimente betreibt. Er hat in Darnassus ein Gebinde rarer Erde bestellt, und die Lieferung kam erst kürzlich mit Verspätung hier in Dolanaar an.\n\nWürdet Ihr ihm dieses Gebinde wohl bringen?", objectives = "Bringt Denalan am Al'Amethsee das Gebinde rarer Erde.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[998] = { title = "Verderbte Windblüte", description = "", objectives = "", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1000] = { title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", objectives = "Sprecht auf der Anhöhe der Ältesten in Thunder Bluff mit dem Erzdruiden Hamuul Runetotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1001] = { title = "Dröhnkiste 411", description = "Aus dem Inneren der Maschine ist eine leise Stimme zu hören.\n\n\"Hier spricht Wizbang! Die nächste Dröhnkiste befindet sich nördlich von Auberdine, am Strand.\n\nAlso, es ist die Dröhnkiste mit der Nummer 411 und es werden 3 Drescheraugen benötigt, um sie zu reparieren. Sie befinden sich direkt vor der Küste! Die Dunkelküstendrescher... *Hick*... Tut mir Leid...\n\nÜbrigens, wie beim letzten Mal wird die Dröhnkiste Eure Belohnung ausspucken, sobald Ihr die Sachen in die Maschine eingebaut habt. *Hick*... Was? Nein, mir geht's gut!\"", objectives = "Besorgt Euch 3 Drescheraugen von den Dunkelküstendreschern im tiefen Meer in der Nähe der Dröhnkiste 411.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1002] = { title = "Dröhnkiste 323", description = "Die Dröhnkiste gibt statische Geräusche von sich, als Wizbang zu sprechen beginnt.\n\n\"Die nächste Dröhnkiste ist Nummer 323. Schteht nördlich von Auberdine, aber... wo's das Bier? Wa...? Oh, schteht direkt an der Straße, kann man gar nicht verfehlen, gleich neben der Brücke.\"\n\nWizbang murmelt wirres Zeug vor sich hin, bevor Ihr ein lautes Schluckgeräusch hört.\n\n\"Der da fehlen Mondpirscherfangzähne... sechs davon.\"", objectives = "Sammelt 6 Mondpirscherfangzähne und baut sie in Dröhnkiste 323 ein.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1003] = { title = "Dröhnkiste 525", description = "Wizbangs zitternde Stimme übertönt die Blubber- und Tropfgeräusche, die aus dem Inneren der Maschine dringen.\n\n\"Näxte is' die Straße weiter runter nach Süden. Is' leicht zu find'n... direkt am Straßenrand... neben ei'm Sssaun. Glaub, ich hab sie hinner'n paar Büscheln verschteckt... Büschen. Hehehe... Jaaa, Dröhnkiste 525 fehlen ergraute Skalps von dies'n grauhaarigen Dischtelbären. Mann, das schpricht sich blöd. Dissstelbär... Hehehe...\"\n\nIhr hört weitere Schluckgeräusche, dann schaltet sich die Maschine aus. Plötzlich erwacht sie jedoch wieder zum Leben.\n\n\"4!\"", objectives = "Sammelt 4 ergraute Skalps von ergrauten Distelbären südlich von Auberdine und legt sie in die Dröhnkiste 525.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1004] = { title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", objectives = "Sprecht auf der Anhöhe der Ältesten in Thunder Bluff mit dem Erzdruiden Hamuul Runetotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1007] = { title = "Die antike Statuette", description = "Ich würde Euch gern eine Aufgabe übertragen, $N.\n\nIch war auf meinem kleinen Schiff und kreuzte über den versunkenen Ruinen von Zoram, als ich plötzlich von Naga angegriffen wurde, die aus dem Wasser stießen und mich mit ihren Klauen beharkten! Ich floh und nahm alle Vorräte mit, die ich tragen konnte, um dieses bescheidene Lager zu errichten.\n\nAls ich jedoch die Küste erreichte und weglief ... verlor ich meinen liebsten Besitz.\n\nBitte, $N, geht zu dem Ort vor der Küste im Norden, an dem ich in den Hinterhalt geriet, und sucht dort nach einer antiken Statuette. Sie ist der Grund, warum ich die Gefahren des Zoramstrands auf mich genommen habe.", objectives = "Bringt Talen im Lager in der Nähe des Zoramstrands die antike Statuette.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1008] = { title = "Der Zoramstrand", description = "Böses lauert an unserer nordwestlichen Küste, die als Zoramstrand bekannt ist.\n\nEs ist die Ruhestätte der untergegangenen Stadt Zoram, die während der großen Teilung zerstört wurde und im Meer versank. Die Nachtelfen verloren sie vor Unzeiten. Sie war verloren und fast vergessen.\n\nJetzt allerdings sind die Naga zurückgekehrt, aber warum, wissen wir nicht. Es ist auch unwichtig. Wir müssen diese Scheusale vernichten und zurück in die Tiefe treiben!\n\nKehrt zu mir zurück, wenn Ihr Eure Mission abgeschlossen habt.", objectives = "Bringt Shindrell Swiftfire in Astranaar 20 Köpfe von Rächerflossen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1009] = { title = "Ruuzel", description = "Ich fürchte, die Geheimnisse der antiken Statuette werden für immer verborgen bleiben, wenn Ihr nicht den Schlüssel zu ihrem antiken Schloss findet.\n\nDieser Schlüssel ist ein Ring, der Ring von Zoram. Er gehörte einst den Herrschern dieser Stadt, bevor sie in den Wellen der großen Teilung unterging.\n\nÜber Jahre hinweg war der Ring verloren, aber die Naga haben ihn vor kurzem gefunden.\n\nRuuzel, ihr Anführer, haust auf einer Insel am Nordrand von Zoram. Bitte, $N, holt mir meinen Ring!", objectives = "Bringt Talen im Lager in der Nähe des Zoramstrands den Ring von Zoram.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1010] = { title = "Bathranshaar", description = "Es gibt eine Pflanze, die früher einmal in den alten Ruinen von Bathrans Schlupfwinkel im Norden wuchs. Die Pflanze namens Bathranshaar war als Heilmittel für Krankheiten des Geistes bekannt.\n\nEin Kind im Dorf ist krank geworden und ich glaube, dass es sich nicht nur um eine körperliche Krankheit handelt. Würdet Ihr wohl zu Bathrans Schlupfwinkel reisen und dort für mich nach Bathranshaar suchen? Ich könnte es brauchen, wenn ich das Kind richtig behandeln soll.\n\nBathrans Schlupfwinkel liegt nördlich von Maestras Posten und gleich südlich der Grenze zu Dunkelküste.", objectives = "Bringt Orendil Broadleaf in Ashenvale 5 Bathranshaar-Pflanzen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1011] = { title = "Verlassenenkrankheit", description = "Die Verlassenen, der untote Arm der Horde, haben sich in Ashenvale eingeschlichen und treiben sich in unseren Ruinen und Grabhügeln herum. Wir glauben, dass sie die Krankheit im Land der Nachtelfen verbreiten wollen. Wir müssen das genau wissen!\n\nDie Verlassenen haben südlich von hier, in der Nähe des Dor'danil-Grabhügels, ein Lager, in dem sie Gifte und Krankheiten entwickeln und in Flaschen füllen. Kämpft Euch in das Lager hinein und stehlt eine Krankheitsflasche. Bringt mir eine solche Flasche. Ich werde sie testen und herausfinden, was sie bewirkt.", objectives = "Bringt Kayneth Stillwind in Forest Song eine Krankheitsflasche.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1012] = { title = "Irrsinnige Druiden", description = "Als ich mich mit den Giften der Verlassenen abplagte, hatte ich eine Vision. Ich sah die Druiden des Dor'danil-Grabhügels vergiftet... ermordet von den Untoten! Sie sind jetzt Geister, die getrennt von ihren Körpern und in den Wahnsinn getrieben ziellos umherirren.\n\nIhr müsst den Dor'danil-Grabhügel betreten und die früheren großen Anführer vernichten, damit die Geister der Druiden eines Tages wieder Frieden finden: Taneel Darkwood, Uthil Mooncall und Mavoris Cloudsbreak.\n\nTut dies und kehrt dann zu mir zurück.", objectives = "Tötet die Druiden Taneel Darkwood, Uthil Mooncall und Mavoris Cloudsbreak und kehrt dann zu Kayneth Stillwind in Forest Song zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1013] = { title = "Das Buch von Ur", description = "$N, in der Burg Shadowfang gibt es ein Buch, das Buch von Ur, das ich unbedingt in meiner Sammlung haben möchte. Ur war einst ein großer Magier aus Dalaran bevor die Geißel kam. Seine Studien anderer Welten sind von großem Wert für... bestimmte Kreise der Verlassenen.\n\nBetretet die Burg Shadowfang und sucht das Buch. Bringt es mir, dann kann ich unserer dunklen Fürstin von Euren Diensten berichten...", objectives = "Bringt dem Bewahrer Bel'dugur im Apothekarium in Undercity das Buch von Ur.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1014] = { title = "Arugal muss sterben", description = "Arugal lebt immer noch in der Burg Shadowfang. Wir können Silberwald erst dann als strategische Festung für die dunkle Fürstin beanspruchen, wenn Arugal erschlagen ist.\n\nIch werde mich darum kümmern, seine Magie zu neutralisieren, $n. Ich überlasse es jedoch Euch, für Arugals Tod zu sorgen, den er mehr als verdient.\n\nReist zur Burg Shadowfang und setzt Arugals üblen Zaubern ein für alle Mal ein Ende. Bringt mir den Kopf dieses niederträchtigen Hexers!", objectives = "Tötet Arugal und bringt Dalar Dawnweaver in dem Grabmal seinen Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1015] = { title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Staghelm, er hat weitere Informationen!", objectives = "Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Staghelm über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1016] = { title = "Elementararmschienen", description = "Nehmt diese Rolle der Bestimmung; sie kann den Schöpfer dieser Elementare bestimmen. Aber Ihr werdet etwas von ihnen benötigen, um es als Reagenz zum Fokussieren der Magie dieser Rolle zu verwenden; ihre Armschienen sollten hervorragend dafür geeignet sein.\n\nEin paar wenige intakte Armschienen dieser Kreaturen dürften reichen. Die anderen Armschienen werden für unsere Zwecke nutzlos sein, aber sie könnten einem Händler etwas wert sein, wenn Ihr sie verkaufen wollt. Nachdem Ihr die intakten Armschienen habt, versucht die Rolle zu verwenden. Kehrt mit den Ergebnissen zu mir zurück und dann werden wir weitersehen.", objectives = "Sammelt 5 intakte Elementararmschienen und wendet die Rolle der Bestimmung darauf an. Bringt danach der Schildwache Velene Starstrike in der Silberwindzuflucht die Rolle der Bestimmung.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1017] = { title = "Magier-Beschwörer", description = "Es gibt nur einen untoten Magier im Brachland, der in der Lage wäre, so viele Wasserelementare zu entweihen. Er ist auch der Einzige, der dumm genug wäre, es zu versuchen. Sarilus Foulborne sitzt wahrscheinlich jetzt gerade oben auf dem Glutnebelgipfel und lacht mich aus.\n\n$N, Ihr müsst Euch in Feindesland begeben und diesen Übeltäter vernichten. Ich habe genug von seinem Schwachsinn und wir müssen ihm zeigen, was mit jenen geschieht, die die Schildwachen verärgern.\n\nVernichtet ihn und bringt mir seinen Kopf. Vorsicht allerdings, die Horde könnte nach Euch Ausschau halten.", objectives = "Erschlagt Sarilus Foulborne und bringt Schildwache Velene Starstrike in der Silberwindzuflucht seinen Kopf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1018] = { title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Weitere Informationen erhaltet Ihr beim Erzdruiden Hamuul Runetotem auf der Anhöhe der Ältesten in Thunder Bluff.", objectives = "Sprecht auf der Anhöhe der Ältesten in Thunder Bluff mit dem Erzdruiden Hamuul Runetotem über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1019] = { title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Staghelm, er hat weitere Informationen!", objectives = "Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Staghelm über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1020] = { title = "Orendils Heilmittel", description = "$N, ich habe ein Heilmittel entwickelt, mit dem man dem erkrankten Kind bestimmt helfen kann. Bringt es nach Astranaar und gebt es dem Vater des Kindes, Pelturas Whitemoon.\n\nUm nach Astranaar zu gelangen, folgt der Straße gen Süden und dann gen Osten.", objectives = "Bringt Pelturas Whitemoon in Astranaar Orendils Heilmittel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1021] = { title = "Elende Satyrn! Die Dryaden sind in Gefahr!", description = "Ich weiß zwar nicht, wer Ihr seid, aber ich brauche Eure Hilfe. Meine Schwestern wollten den Satyrn den Zweig des Cenarius abnehmen. Sie sagten, dass sie bald zurück sein werden, aber das war vor zwei vollen Tagen!\n\n$N, Ihr müsst sie finden! Sie wollten nach den Ruinen eines Nachtelfentempels in Xavian im Nordosten suchen. Ich weiß nicht, was ich davon halten soll. Sucht nach Anilia, sie wollte sie bei der Suche führen.", objectives = "Sucht in Xavian nach Anilia.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1022] = { title = "Das Heulende Tal", description = "Obwohl wir viele Mittel und große Bemühungen investiert haben, um auch die letzten Dämonen aus dem Teufelswald im Norden zu vertreiben, hatten wir nur wenig Erfolg damit. Wir konnten jedoch einen Großteil der Dämonen von Ashenvale fern halten.\n\nIm Norden, nahe der Grenze zum Teufelswald, wurde der verfallene Mel'Thandris-Schrein von rätselhaften Wolfmenschen übernommen. Ihre Schreie, die einem das Blut in den Adern gerinnen lassen, haben dem als \"Das heulende Tal\" bekannten Gebiet seinen Namen gegeben. Der Foliant von Mel'Thandris, der im Schrein aufbewahrt wird, könnte etwas Licht darauf werfen, warum die Wolfmenschen hier sind.", objectives = "Begebt Euch ins heulende Tal, studiert den Folianten von Mel'Thandris und kehrt dann zur Schildwache Melyria Frostshadow beim Schrein von Aessina zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1023] = { title = "Raenes Säuberung", description = "Während Ihr Teronis Habseligkeiten durchstöbert, stoßt Ihr auf ein Tagebuch, das noch in gutem Zustand ist.\n\nIhr nehmt das Tagebuch und lasst Teronis' Kadaver so wie er ist zurück.\n\nJetzt müsst Ihr nur noch eines tun: den Edelstein finden, den Teronis suchte. Raene deutete an, dass er sich in diesem Gebiet befinden würde. Vielleicht haben ihn die Murlocs ...", objectives = "Sucht den leuchtenden Edelstein und bringt ihn zusammen mit Teronis' Tagebuch zu Raene Wolfrunner in Astranaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1024] = { title = "Raenes Säuberung", description = "Ihr werdet selbst Nachforschungen anstellen müssen, aber gemäß Teronis' Notizen scheint es unsere nächste Aufgabe zu sein, die anderen Teile der Rute zu finden, die Dartol erschuf. Ich würde mich zunächst zum Mondbrunnen östlich des Irissees begeben. Wenn Ihr bereit seid, folgt der Straße und wendet Euch gen Norden, wenn Ihr einen kleinen Sitzbereich zu Eurer Linken erreicht.\n\nDort findet Ihr eine Dryade namens Shael'dryn, die Euch eine bessere Führerin sein wird. Sucht sie auf.\n\nBehaltet den Edelstein - Shael'dryn wird ihn brauchen, um Euch bei der Wiederherstellung der Rute zu helfen.", objectives = "Sucht Shael'dryn beim Mondbrunnen im Nordosten auf.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1025] = { title = "Eine aggressive Verteidigung", description = "Bevor Ihr zum Mondbrunnen aufbrecht, habe ich noch eine andere Aufgabe für Euch, wenn Ihr gern Eure Fertigkeiten auf die Probe stellen und dem Volk von Ashenvale helfen würdet.\n\nEntlang der Straße, die nach Osten führt, haben Furbolgs kurz vor dem Falfarren Reisende angegriffen. Ihre gequälten Seelen nähren sich von Angst und sie stillen ihren Appetit mit dem Blut Unschuldiger.\n\nHelft den Schildwachen, das Land zu schützen, indem Ihr diesen Monstern dieselbe Gnade zeigt, die sie uns erwiesen haben.\n\nIch glaube, ihre Lager liegen südlich der Straße ... seid vorsichtig.", objectives = "Tötet 1 Höhlenbehüter, 2 Ursa, 10 Totemiker sowie 12 Krieger der Fäulnisklauen und kehrt dann zu Raene Wolfrunner in Astranaar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1026] = { title = "Raenes Säuberung", description = "Ich wünschte, Ihr hättet bessere Nachrichten.\n\nRaene hat Recht, ich weiß von Dartols Werk und den Treants, den Baumwesen in diesem Gebiet - zumindest wusste ich es einst. Heute sind sie verderbt, ihre Natur verzerrt.\n\nFalls es Euer Ziel ist, das nächste Teil der Rute zu finden, solltet Ihr zunächst den Schlüssel suchen, mit dem die Truhe geöffnet werden kann, in dem es sich befindet.\n\nEiner der Treants nordöstlich von hier in der Nähe des Teufelswalds hat ihn. Sobald Ihr ihn habt, sucht nach einem kleinen Tal westlich der Straße nahe der Grenze zum Teufelswald... die Truhe ist dort irgendwo versteckt.", objectives = "Sucht den hölzernen Schlüssel und das Teil von Dartols Rute, bevor Ihr zu Shael'dryn beim Mondbrunnen zurückkehrt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1027] = { title = "Raenes Säuberung", description = "Das letzte Teil der Rute wurde in die Obhut der Druiden von Dor'danil gegeben. Ich habe keine Ahnung, wo sie es versteckt haben. Es tut mir Leid, dass ich Euch da nicht weiterhelfen kann.\n\nIch kann Euch nur sagen, folgt der Straße, die zum Brachland führt. Die Druiden suchten östlich dieser Straße Zuflucht, aber sie werden Euch nicht viel helfen können: Sie wurden kürzlich getötet ... Ich mag gar nicht darüber nachdenken.\n\nWenn Ihr das letzte Teil gefunden habt, bringt es mir, dann helfe ich Euch, die Rute wieder zusammenzusetzen.", objectives = "Sucht das letzte Teil von Dartols Rute und bringt es Shael'dryn beim Mondbrunnen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1028] = { title = "Raenes Säuberung", description = "Hier habt Ihr die vollständige Rute, $n. Es war nicht schwer, sie wieder zusammenzusetzen... Den Schrein zu finden, der die Kraft hat, sie wieder aufzuladen, ist der schwierige Teil.\n\nMit etwas Konzentration und Einsatz sollte es für jemanden wie Euch, der bereits so viel erreicht hat, allerdings nicht zu schwer sein.\n\nGeht von hier aus nach Südosten - es gibt nur wenige Wege, also seid vorsichtig - und behaltet immer den Norden im Auge. Der Schrein liegt in den Bergen verborgen, die dieses Tal umgeben.\n\nDort angekommen legt Ihr die Rute in den Schrein... der Rest ist Magie. Hehe.", objectives = "Sucht den verborgenen Schrein und verzaubert Dartols Rute erneut.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1029] = { title = "Raenes Säuberung", description = "Ich schlage vor, dass Ihr Raene aufsucht und sie wissen lasst, dass die Rute fertig gestellt ist. Sie weiß bestimmt, was Ihr als Nächstes tun solltet.\n\nViel Glück, $N.", objectives = "Kehrt zu Raene Wolfrunner in Astranaar zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1030] = { title = "Raenes Säuberung", description = "Leider bin ich mir nicht ganz sicher, was er als Nächstes vorhatte.\n\nWenn es wahr ist, was er über die Macht der Rute sagte, könnt Ihr mit ihrer Hilfe eine völlig andere Gestalt annehmen. Welche Gestalt weiß ich allerdings nicht.\n\nVielleicht wollte er ihre Kräfte nutzen, um näher an die besudelten Furbolgs heranzukommen, aber selbst die nicht verderbten Kreaturen hätten ihn getötet, wäre er nicht vorsichtig gewesen. Durch die Rute verwandelt, hätte Dartol wahrscheinlich mit einem Furbolg gesprochen, der gegen die Auswirkungen des Teufelsmooses gefeit ist.\n\nIhr solltet Eure Suche südöstlich des Mystralsees beginnen.", objectives = "Sucht einen nicht verderbten Furbolg und benutzt die Macht von Dartols Rute der Transformation, um mit ihm zu sprechen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1031] = { title = "Der Zweig des Cenarius", description = "Anilia legt Euch die Hände auf die Schultern und zieht Euch zu sich heran. Nach Luft ringend zeigt sie in Richtung des Bogens im Norden, bevor sich ihre Augen schließen und sie einen letzten, keuchenden Atemzug ausstößt. \"Er hat ihn... Geltharis...\" In Eurem Herzen wisst Ihr, dass es Anilias letzter Wunsch war, den Zweig des Cenarius wieder in den Händen der Dryaden zu sehen.", objectives = "Tötet Geltharis und bringt Illiyana beim Schrein von Aessina den Zweig des Cenarius.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1032] = { title = "Satyrn schlachten!", description = "Ich kann nicht glauben, dass Anilia von uns gegangen ist... Wir haben doch immer zusammen in den Wäldern gespielt. Ich fühle beinahe so etwas wie... Trauer.\n\nEs gibt aber etwas, das mich vielleicht aufheitern könnte! Bitte, erschlagt die Satyrn, die mir Anilia genommen haben! Bringt mir ihre Hörner als Beweis Eurer Taten und Ihr könnt Euch auf ewig meines Dankes gewiss sein.", objectives = "Bringt Illiyana im Schrein von Aessina 16 Satyrhörner.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1033] = { title = "Elunes Träne", description = "Ich hatte gehofft, Orendils Heilmittel würde Relara retten, aber ich fürchte, es hat die Krankheit, die in meinem Kind wütet, nur gedämpft. Wir müssen eine stärkere Medizin finden! Zum Glück hat mir Orendil von weiteren Arzneien erzählt, sollte seine Erste versagen.\n\nTräne von Elune ist eine Gesteinsart, die nur an einem Ort vorkommt: auf der Insel im Irissee, östlich von Astranaar. Orendil sagte, der Stein könne Verderbnis wegwaschen ... Bitte, $N, bringt mir eine Träne von Elune und betet, dass sich die Erkrankung meiner Tochter damit heilen lässt!", objectives = "Bringt Pelturas in Astranaar die Träne von Elune.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1034] = { title = "Die Sternenstaubruinen", description = "Die Träne von Elune hat einen Teil der Erkrankung meiner Tochter weggewaschen. Ihre Alpträume haben nachgelassen und ich danke der Göttin für ihren Segen. Aber... immer noch wütet das Fieber in ihr.\n\nOrendil erzählte mir von einem gefrorenen Staub, den man in den Sternenstaubruinen findet. Vielleicht kann man damit Relaras Fieber senken. Sammelt etwas von diesem Staub und kommt dann bitte wieder zu mir zurück.\n\nDie Sternenstaubruinen liegen im Süden, $N. Möge Elune Eure Reise beschleunigen.", objectives = "Bringt Pelturas in Astranaar 5 Hand voll Sternenstaub.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1035] = { title = "Fallenskysee", description = "Relara hat kein Fieber mehr, aber sie ist immer noch sehr schwach. Ich glaube nicht, dass sie wieder zu Kräften kommt, wenn wir einfach nur abwarten. Ich glaube, dazu bedarf es der Kraft eines Mondsteins.\n\nWir haben Mondsteine früher immer beim Fallenskysee im Südosten gesammelt... bis die Schattendickichtbäumlinge kamen.\n\nIhr Anführer, das Schattendickichtorakel, hat alle gefallenen Mondsteine eingesammelt und hortet sie. Jetzt müsst Ihr Euch einen Mondstein von dem Orakel holen.\n\nUnd dazu werdet Ihr ihn wohl erschlagen müssen, fürchte ich.", objectives = "Holt von dem Schattendickichtorakel einen gefallenen Mondstein und bringt ihn Pelturas in Astranaar.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1036] = { title = "Hierher, Taugenichts", description = "$n... Ja, ich habe von Euch gehört. Ich habe gehört, dass Ihr kein Freund von Beutebucht seid - genau wie wir Blutsegelbukaniere. Flottenmeister Firallon sucht nach gesunden und tüchtigen $gMännern:Frauen; wie Euch für eine spezielle Mission.\n\nWenn Ihr interessiert seid, begebt Euch zur Purpurschleier und sprecht mit ihm unter Deck. Sie ankert vor der wilden Küste östlich von hier, bei der Springflut und der Maid im Glück.", objectives = "Sprecht mit Flottenmeister Firallon an Bord der Purpurschleier vor der Küste des Schlingendorntals.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1037] = { title = "Velinde Sternensang", description = "Velinde Starsong war hier in Ashenvale meine Vorgängerin. Zunächst schien es, als hätte sie die Lage im Teufelswald unter Kontrolle, aber nach und nach ließen ihre Bemühungen nach. Eines Tages verschwand sie einfach.\n\nMan schickte mich hierher, um ihre Arbeit fortzusetzen. Ich fürchte jedoch, dass ich nichts über die Priesterin weiß. Vielleicht weiß Thyn'tel Bladeweaver, eine der Kommandantinnen der Schildwache, mehr über ihr Verschwinden, das ich nicht miterlebt habe.\n\nSie wird sicherlich wissen, wie wichtig diese Informationen sind.", objectives = "Sprecht auf der Terrasse der Krieger in Darnassus mit Thyn'tel Bladeweaver.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1038] = { title = "Velindes Besitztümer", description = "Der Foliant von Mel'Thandris hat Euch das gezeigt? Dann könnte es wohl nicht schaden, wenn ich Euch erlaubte, ihre Habseligkeiten durchzusehen. Mit diesem Schlüssel könnt Ihr die Truhe öffnen, in der wir ihre Sachen in der Schildwachenbaracke aufbewahren. Sie führte ein Tagebuch über ihre Pflichten und wenn es etwas zu erfahren gibt, dann daraus.\n\nIch sollte Euch noch sagen, dass die Schildwachen denken, dass sie Gründe für ihr Verschwinden hatte und damit rechnen, dass sie jederzeit wieder auftaucht. Die Priesterin hat in der Vergangenheit viel geleistet und unser Vertrauen verdient.", objectives = "Durchsucht Velindes Truhe nach ihrem Tagebuch und bringt es zusammen mit dem Schlüssel nach Darnassus zu Thyn'tel Bladeweaver.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1039] = { title = "Der Brachlandhafen", description = "Ratchet ist der einzige Hafen des Brachlandes. Höchstwahrscheinlich hat Velinde in Ratchet ein Handelsschiff gefunden, das sie zur Schwarzmeerbucht in Azeroth brachte. Wir haben nur wenig mit den Goblins zu tun, die den Hafen leiten, aber der Dockmeister sollte über das Kommen und Gehen von Schiffspassagieren informiert sein.\n\nFolgt der Straße in südöstlicher Richtung durch Ashenvale, dann gelangt Ihr irgendwann ins Brachland. Seid auf der Hut, $n, Krieger der Horde streifen durch das Land. Im Hafen werdet Ihr jedoch sicher sein.", objectives = "Sprecht in Ratchet mit Werftmeister Dizzywig.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1040] = { title = "Passage nach Booty Bay", description = "Ah ja, da steht's ja. Hättet mir sagen sollen, dass sie vor so langer Zeit hier durchgekommen ist. Mal sehen.\n\nVelinde. Hat eine Passage auf der BLACK OSPREY nach Booty Bay gebucht. Da hier nichts anderes steht, nehme ich an, dass sie den Hafen dort sicher erreicht hat.\n\nViel mehr Hilfe kann ich Euch nicht anbieten, aber sie hat mich nach einem Überlandtransport zur anderen Seite der Welt gefragt und ich habe ihr Ruzzgot vorgeschlagen, einen Karawanenführer aus Booty Bay. Kann sein, dass Velinde mit ihm gereist ist.\n\nUnd jetzt fort mit Euch. Ich hab zu tun.", objectives = "Nehmt ein Schiff nach Booty Bay und sprecht dort mit dem Karawanenführer Ruzzgot.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1041] = { title = "Die Karawanenstraße", description = "Da hab ich mich wohl in Euch getäuscht und das passiert mir nicht alle Tage.\n\nZufällig erinnere ich mich an diese Velinde, nach der Ihr sucht. Kommt nicht jeden Tag vor, dass eine Nachtelfenpriesterin mit einer schmutzigen alten - aber alle Transportwünsche erfüllenden - Karawane wie der meinigen reisen will.\n\nAuf dem Weg nach Norden trennten wir uns, sie wollte weiter nach Dunkelhain. Der Amtmann dort macht alle möglichen Aufzeichnungen. Kann sein, dass er etwas Nützliches weiß.\n\nSeid im Dschungel vorsichtig, der ist selbst in günstigsten Zeiten tödlich.", objectives = "Sprecht in Dunkelhain mit Amtmann Daltry.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1042] = { title = "Die Familie Carevin", description = "Nein, ich habe keinen Eintrag über eine Velinde Starsong, die sich in Dunkelhain aufgehalten haben soll... Wenn Ihr erlaubt, ich kann mir auch nicht vorstellen, dass eine Nachtelfenpriesterin sich in einem Gasthaus einquartiert, wenn Ihr wisst, was ich meine.\n\nDiese Wolfmenschen, die Ihr erwähntet, von denen hab ich schon mal gehört. Erst kürzlich kam Calor mit einer ganzen Reihe Köpfe von denen in die Stadt zurück. Er arbeitet für die Familie Carevin. Sie jagen Dämonen, Untote und andere Monster. Sprecht mit Jonathan, er ist der Haushaltsvorstand.", objectives = "Sprecht mit Jonathan Carevin in Dunkelhain.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1043] = { title = "Die Sense von Elune", description = "Eure Geschichte klingt glaubhaft... Ich habe Eure Beweggründe zwar noch nicht ganz begriffen, aber wenn es zu Euren Angelegenheiten hier im Dämmerwald gehört, die Worgs im Wald auszurotten, dann können mir Eure Beweggründe auch herzlich egal sein, solange das Ergebnis stimmt.\n\nIm Süden gibt es eine Mine, die von Worgs überrannt wurde... Sie kamen aus dem Nichts, aber nach allem, was wir wissen, hat man sie dort zuerst gesehen.\n\nGeht Ihr nur Euren Angelegenheiten nach, aber ich möchte Euch bitten, dass Ihr mir Bescheid gebt, sobald Ihr etwas Wichtiges entdeckt. Wir sind für jede Hilfe gegen das Böse dankbar.", objectives = "Sucht nach Hinweisen auf die Sense von Elune und kehrt dann zu Jonathan Carevin in Dunkelhain zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1044] = { title = "Beantwortete Fragen", description = "Wir werden das Worgproblem in den Griff bekommen, keine Frage. Das Böse, das Eure Freundin in unseren Wald gebracht hat, wird eingedämmt werden und ich nehme ihr ihre Handlungen nicht übel. In letzter Zeit gehen seltsame Dinge vor sich, $n, und die Dunkelheit kennt keine Atempausen.\n\nIch will Euch nicht länger aufhalten. Mir scheint, dass auch andere erfahren sollten, was Ihr in den Minen des Dämmerwalds entdeckt habt.", objectives = "Kehrt nach Darnassus zu Thyn'tel Bladeweaver zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1045] = { title = "Raenes Säuberung", description = "Die Nachtelfen sind so alt wie die Zeit, aber sie zerstören ihre eigene Welt durch ihre Arroganz. Und jetzt zerstören sie auch noch unser Leben. Doch das kann man nicht mehr verhindern...\n\nIch gebe den Elfen für viele Dinge die Schuld, aber wir sind immer noch für unsere Handlungen selbst verantwortlich. Wir sind sogar trotz der Verderbnis noch zu jeder Menge Bösem fähig.\n\nRan Blutreißer ist einer dieser Bösen. Machthungrig, gierig... die Verderbnis hat ihn nur noch stärker gemacht. Mein Hass auf die Elfen lodert, aber ich wünsche ihren Kindern nichts Schlimmes, wir müssen uns selbst im Zaum halten.", objectives = "Tötet Ran Blutreißer sowie 4 Wachen von Blutreißer und kehrt dann zu Krolg in der Nähe des Mystralsees zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1046] = { title = "Raenes Säuberung", description = "Kehrt zu Eurem eigenen Stamm zurück und lasst ihn von Eurem Sieg hier wissen.\n\nZeigt ihm Eure Trophäe und sonnt Euch in Eurem Ruhm...", objectives = "Bringt Raene Wolfrunner in Astranaar Ran Blutreißers Schädel und Dartols Rute der Transformation.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1047] = { title = "Die neue Grenze", description = "Aufgemerkt, Helden!\n\nDer Zirkel des Cenarius sucht nach einsatzfähigen Individuen, die dazu beitragen möchten, ihn bei der Erforschung der riesigen neuen Grenzgebiete Kalimdors zu unterstützen! Weit im Westen von Tanaris und Gadgetzan liegt eine abschreckende Ödnis voller unvorstellbarer Gefahren, und der Zirkel braucht ehrbare und gewillte Vertreter, die an seiner statt agieren.\n\nInteressenten mögen bitte zwecks einer Audienz beim Zirkel des Cenarius vorstellig werden. Sprecht in Darnassus mit dem Erzdruiden Fandral Staghelm, er hat weitere Informationen!", objectives = "Sprecht in der Enklave des Cenarius in Darnassus mit dem Erzdruiden Fandral Staghelm über den Aufruf des Zirkels des Cenarius zur Erforschung der Grenzgebiete von Kalimdor.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1048] = { title = "In das Scharlachrote Kloster", description = "Während die dunkle Fürstin sich um die dringende Angelegenheit des Vormarsches des Lichkönigs im Norden kümmert, sorge ich dafür, dass Dinge, die uns unmittelbar betreffen, entsprechend geregelt werden.\n\nDie Menschenplage, die sich selbst Scharlachroter Kreuzzug nennt, hat sich als der schärfste Dorn in unserem Fleisch erwiesen. Tirisfal wimmelt förmlich von diesen kleinen roten Ameisen.\n\nBegebt Euch zum Kloster, $C, und vernichtet Hochinquisitor Whitemane und seine obersten Offiziere.", objectives = "Tötet Hochinquisitor Whitemane, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Varimathras in Undercity.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1049] = { title = "Kompendium der Gefallenen", description = "Der Irdene Ring hatte nur die besten Absichten, was unsere geplagten Brüder betraf. Aber wer weiß schon, welche Absichten jene verfolgen, die dem Ältestenrat Dinge einflüstern?\n\nDie Geschichte der Verlassenen, mit denen wir uns verbündet haben, ist von Lug und Trug durchzogen. Zu übereilt gingen wir unseren Pakt ein. Vielleicht hätte Cairne gut daran getan, die Warnungen aus Orgrimmar zu beherzigen.\n\nTief im Inneren des Scharlachroten Klosters liegt das 'Kompendium der Gefallenen' verborgen, das von irren menschlichen Zeloten bewacht wird. Ihr Tun ist von ihrem Wahnsinn geprägt, aber ihre Forschungen könnten nützlich für uns sein.", objectives = "Holt das 'Kompendium der Gefallenen' aus dem Kloster in Tirisfal und bringt es zu Sage Truthseeker in Thunder Bluff.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1050] = { title = "Mythologie der Titanen", description = "Die Zukunft ist unausweichlich! Wir stürzen ihr entgegen wie Regentropfen, die auf das Große Meer prasseln.\n\nAber vielleicht erfahren wir, indem wir die Vergangenheit studieren, was uns erwartet, und könnten uns besser auf das Unbekannte vorbereiten.\n\nBevor Lordaeron von all diesen schrecklichen Dingen heimgesucht wurde, gab es eine Bastion des Wissens, die in Tirisfal versteckt lag. Gerüchten zufolge soll es in der Bibliothek des alten Klosters ein Buch mit dem Titel 'Mythologie der Titanen' gegeben haben.\n\nBringt es mir, dann können wir vielleicht gemeinsam die Geheimnisse der Vergangenheit entschlüsseln!", objectives = "Holt die 'Mythologie der Titanen' aus dem Kloster und bringt die der Bibliothekarin Mae Paledust in Ironforge.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1051] = { title = "Vorrels Rache", description = "Trotz meines freien Willens kann ich der dunklen Fürstin nicht mehr dienen. Ich fühle, dass meine Zeit in Azeroth zu Ende geht. Meine Lebenskraft ist zerschmettert.\n\nDas hat mir Befrager Vishas angetan! Wochenlang quälte er mich! Nahm mir meinen Ehering und gab ihn seiner Frau. Dieser Bastard!\n\nRache ... Ich will Rache!\n\nDer eingebildete Narr prahlte immer mit seiner ach so kostbaren Frau Nancy, die am Lordameresee lebte. Spürt diese Frau auf, erschlagt sie und bringt meiner Frau Monika in Tarrens Mühle meinen Ehering.\n\nDies ist mein letzter Wille ...", objectives = "Bringt Monika Sengutz in Tarrens Mühle den Ehering von Vorrel Sengutz.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1052] = { title = "Auf dem Scharlachroten Pfad", description = "Wir vom scharlachroten Kreuzzug erheben Anspruch auf die Festungen zwischen Hearthglen und Tirisfal. Wir sind recht stolz auf unsere Bastionen der Säuberung in ganz Lordaeron.\n\nIhr habt Euch gegen die Untoten in Desolace bewiesen. Doch die wahre Bedrohung durch die Seuche liegt in Lordaeron.\n\nBegebt Euch nach Southshore in den östlichen Königreichen. Sucht dort nach einem Kreuzzügler namens Raleigh der Andächtige. Gebt ihm dieses Empfehlungsschreiben, das mein Siegel trägt, dann wird er Euch zu einem ehrwürdigen Ort in unserem scharlachroten Kloster führen.", objectives = "Bringt Raleigh dem Andächtigen in Southshore Bruder Antons Empfehlungsschreiben.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1053] = { title = "Im Namen des Lichts", description = "Einst diente ich dem Scharlachroten Kreuzzug mit Ehre, Treue und Stolz. Ich hielt das Ziel, das sie verfolgten, für edel: Azeroth von den Untoten befreien.\n\nAls ich jedoch im Kloster in Tirisfal weilte, erkannte ich, dass sie langsam den Bezug zur Wirklichkeit verloren. Jetzt halten sie jeden für verseucht, der nicht das Wams des Kreuzzuges trägt. Unschuldige Männer und Frauen wurden gefoltert, weil sie angeblich verseucht waren. \n\nDer Scharlachrote Kreuzzug muss im Namen des Lichts zerschlagen werden. Ihr, $n, müsst ihr wahnwitziges Regime beenden.", objectives = "Tötet Hochinquisitor Whitemane, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Raleigh dem Andächtigen in Southshore.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1054] = { title = "Die Auswahl der Bedrohung", description = "Direkt im Norden Astranaars leben die Furbolgs vom Distelfellstamm. Meine Späher berichten, dass ihre Zahl sich in den letzten Monaten erhöht hat. Sollten es zu viele werden, könnten sie den Mut finden, Astranaar direkt anzugreifen.\n\nTötet so viele von ihnen, wie Ihr könnt, aber bringt mir den Schädel ihres Häuptlings zum Beweis dafür, dass ihr Bemühen im Keim erstickt wurde ... vorläufig.\n\nIch bleibe hier in Astranaar und warte auf Kunde von Euch. Elune sei mit Euch.", objectives = "Bringt Raene Wolfrunner in Astranaar Dal Blutklaues Schädel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1055] = { title = "Raenes Säuberung", description = "Die Rute, jetzt wieder heil, liegt in Euren Händen. Shael'dryn wird von Eurem Erfolg hören wollen.", objectives = "Kehrt zu Shael'dryn beim Mondbrunnen zurück.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1056] = { title = "Reise zum Steinkrallengipfel", description = "Die Waldgeister sagten mir, dass Ihr mutig und zu reisen gewillt seid.\n\nIm Süden, nicht weit vom Mystralsee entfernt, liegt ein Tunnel namens Steinkrallenpfad. Durch diesen Tunnel gelangt Ihr in ein Gebiet, das im Steinkrallengebirge als Scherwindklippe bekannt ist. Dort angelangt reist südwestlich weiter, am Felskesselsee vorbei und dann nach Norden, den steilen Abhang hinauf, bis Ihr den Steinkrallengipfel erreicht.\n\nDort werdet Ihr von Hüter Albagorm erwartet. Tut, was er sagt, $R.\n\nDie Reise wird gefährlich.", objectives = "Reist zu Bewahrer Albagorm auf dem Steinkrallengipfel.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1057] = { title = "Die Rückeroberung des Verbrannten Tals", description = "Als Beschützer der Waldgeister könnt Ihr sicher unschwer erraten, warum ich beunruhigt bin.\n\nIhr seid durch diese Berge gereist, um diesen Gipfel zu erreichen. Sicherlich habt Ihr das Zerrbild gesehen, zu dem das Land geworden ist. Gier hat zur Zerstörung dieser heiligen Hügel geführt.\n\nDie gierige motorisierte Armee der Industrialisten hat das verbrannte Tal im Süden in Brand gesteckt. Was noch schlimmer ist, die Blutfurien, die in unser Land eingedrungen sind, lassen uns nicht dorthin, um mit der Neuanpflanzung zu beginnen.\n\nVertreibt diese elenden Harpyien, $n!", objectives = "Bewahrer Albagorm auf dem Steinkrallengipfel möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1058] = { title = "Jin'Zils Waldmagie", description = "Ich bin ja so aufgeregt!\n\nDrei kleine Käfige mit drei kleinen Elfen! Aber was tun wir nur mit unseren süßen Baumschützer-Freunden? Na, lassen wir sie doch... wie nennen sie das doch gleich... Waldmagie schmecken!\n\nIch brauche einen ordentlichen Schuss Steinkrallensaft. Dann brauche ich ein paar Mondlichtläuferschnurrhaare von diesen schrecklichen Katzen. Das schreit nach einer Menge Renneraugen - man kann nie genug Augen haben. Oh, und bevor wir es vergessen, die wertvolle Schuppe eines Siechdrachen.\n\nSchnell zum Steinkrallengipfel, $n, damit ich etwas Waldmagie zusammenbrauen kann!", objectives = "Hexendoktor Jin'Zil in Malaka'jin möchte 5 Portionen Steinkrallensaft, 5 Schnurrhaare eines Mondlichtläufers, 30 Renner-Augen und die Schuppe eines Siechdrachen.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1059] = { title = "Die Rückeroberung des Verbrannten Tals", description = "Die Blutfurien wurden besiegt. Sie werden sich jedoch schon bald wieder neu gruppieren, wenn wir nichts unternehmen.\n\nGanz weit im Süden des Brachlandes liegt ein Land, das als Tausend Nadeln bekannt ist. Wenn Ihr in Tausend Nadeln nach Westen reist bis zum üppigen Waldrand von Feralas, stoßt Ihr auf einen Druiden namens Falfindel Waywarder.\n\nDieser große und weise Druide kann große Waldgeister herbeirufen, die bei der Rekultivierung des verbrannten Tals helfen können.\n\nErzählt ihm von unserer Notlage! Sucht ihn sofort auf!", objectives = "Reist zu Falfindel Waywarder an der Grenze zwischen Tausend Nadeln und Feralas.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1060] = { title = "Brief an Jin'Zil", description = "Ihr habt mir sehr geholfen, $n. Ihr seid ein echter Glücksbringer, wie eine Hasenpfote, und ich möchte, dass Ihr Euch das hier einmal anseht.\n\nDie Harpyien stammen nicht aus dem Brachland. Sie kommen aus einem Ort namens Steinkrallengebirge, ganz weit nordwestlich von hier. Dort könnte es möglicherweise gefährlich für Euch sein, aber dieser Brief muss an einen alten Freund von mir überbracht werden, der dort lebt, ein Hexendoktor mit dem Namen Jin'Zil.\n\nEr wird sich freuen zu hören, dass Serena Blutfeder tot ist, und ich glaube, Ihr werdet das Steinkrallengebirge sehr interessant finden.", objectives = "Überbringt Jin'Zil in seiner Höhle im Steinkrallengebirge Darsoks Brief.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
quests[1061] = { title = "Die Geister des Steinkrallengebirges", description = "Die Geister des Steinkrallengebirges sind verärgert, weil Goblins und ihre Gefolgsleute das Land ausplündern und brandschatzen. Das Land rief um Hilfe, und jene, die auf so etwas achten... haben es gehört.\n\nSeereth Stonebreak, eine aufstrebende Schamanin der Horde, wurde in das Steinkrallengebirge geschickt. Sie berichtet von umfangreichen Rodungen durch die Goblins und bittet um Hilfe.\n\nTrefft Euch im Steinkrallengebirge mit Seereth. Um zu ihr zu gelangen, folgt der Straße westlich aus Crossroads im Brachland. Sie hat in der Nähe des Hochwipfeltals ein Lager aufgeschlagen.", objectives = "Sprecht im Steinkrallengebirge mit Seereth Stonebreak.", source = "pfQuest Vanilla 104f35678ca39ab1fb78b655f815cc7016f5e0c8", flavor = "classic", originFlavor = "classic", locale = "deDE" }
